import{r as ee}from"./jsx-runtime-BguD1OXD.js";var e=`https://learn.microsoft.com/en-us/`,t=`${e}fabric/fundamentals/roles-workspaces`,te=`${e}fabric/fundamentals/give-access-workspaces`,ne=`${e}analysis-services/tmsl/tmsl-reference-commands`,n=`${e}fabric/security/permission-model`,r=`${e}fabric/fundamentals/share-items`,re=`${e}fabric/fundamentals/workspaces`,ie=`${e}fabric/data-warehouse/row-level-security`,ae=`${e}fabric/data-warehouse/column-level-security`,oe=`${e}fabric/data-warehouse/sql-granular-permissions`,se=`${e}fabric/data-warehouse/dynamic-data-masking`,i=`${e}fabric/onelake/security/get-started-security`,ce=`${e}fabric/onelake/security/data-access-control-model`,le=`${e}fabric/onelake/security/onelake-security-integrations-overview`,ue=`${e}fabric/security/service-admin-row-level-security`,de=`${e}fabric/security/service-admin-object-level-security`,fe=`${e}fabric/data-engineering/lakehouse-sql-analytics-endpoint`,pe=`${e}fabric/fundamentals/direct-lake-overview`,me=`${e}fabric/fundamentals/direct-lake-how-it-works`,he=`${e}fabric/fundamentals/direct-lake-security-integration`,a=`${e}fabric/governance/information-protection`,o=`${e}fabric/governance/endorsement-overview`,ge=`${e}fabric/cicd/git-integration/intro-to-git-integration`,s=`${e}fabric/cicd/git-integration/git-integration-process`,c=`${e}power-bi/developer/projects/projects-overview`,l=`${e}fabric/cicd/deployment-pipelines/intro-to-deployment-pipelines`,_e=`${e}fabric/cicd/deployment-pipelines/get-started-with-deployment-pipelines`,u=`${e}fabric/cicd/deployment-pipelines/understand-the-deployment-process`,ve=`${e}fabric/cicd/deployment-pipelines/create-rules`,d=`${e}fabric/governance/impact-analysis`,ye=`${e}fabric/governance/lineage`,f=`${e}fabric/enterprise/powerbi/service-premium-connect-tools`,be=`${e}analysis-services/tmsl/refresh-command-tmsl?view=sql-analysis-services-2025`,xe=`${e}fabric/enterprise/powerbi/service-premium-large-models`,p=`${e}power-bi/create-reports/desktop-templates`,Se=`${e}power-bi/connect-data/desktop-data-sources`,m=`${e}power-bi/connect-data/service-datasets-across-workspaces`,Ce=`${e}power-bi/fundamentals/desktop-get-the-desktop`,we=`${e}power-bi/transform-model/calculation-groups`,Te=[{machineId:`gate-keys`,pl300Adds:[{text:`The four workspace roles are the same as in Power BI, but Fabric extends them to new item types. For example, Contributors can create warehouses and mirrored databases, all roles can read pipelines and notebooks, and only Admins can connect the workspace to Git or create a workspace identity.`,sources:[t]},{text:`Fabric separates the control plane (what you can do with items) from the data plane (what data you can see). Workspace roles also grant data access by default, which you narrow with OneLake security, SQL security, or semantic model RLS.`,sources:[i,n]}],overview:[{text:`Workspace-level access is the outermost gate. Anyone without a workspace role can’t open the workspace at all (unless an item is shared with them directly). Roles apply to every item in the workspace, so this is the broadest control.`,sources:[n]}],bullets:[{bulletId:`M1.1`,tools:[`workspace`],concepts:[{text:`Admin: view, modify, share, and manage everything, including permissions, deleting the workspace, adding admins, connecting to Git. Member: view, modify, and share, and add members or lower roles. Contributor: view and modify content and create items. Viewer: view only.`,sources:[n,t]},{text:`Roles can be assigned to users, security groups, Microsoft 365 groups, distribution lists, and service principals. A user in several groups gets the highest role they’re assigned.`,sources:[t]},{text:`Admins, Members, and Contributors already have data access through write permission. OneLake security default roles mainly matter for Viewers.`,sources:[i,ce]}],howTo:[{text:`Use the workspace’s Manage access option to add people or groups and pick a role. Learn recommends assigning roles to security groups and managing membership in the group.`,sources:[te,re,t,i]}]}],examples:[],traps:[{text:`Workspace roles apply only to that workspace, not to the capacity or tenant.`,sources:[n]},{text:`Semantic model RLS and OLS apply only to Viewers. Admins, Members, and Contributors bypass them because they have edit permission on the model.`,sources:[ue,de]},{text:`Only Admins can connect a workspace to Git or create a workspace identity. Member is not enough.`,sources:[t,s]}],dontConfuse:[{pairId:`member-vs-contributor`,a:`Member`,b:`Contributor`,difference:[{text:`Both can create and modify content. Member can also share items, let others reshare, and add people with Member or lower roles. Contributor can’t manage workspace access, and can share items only if given Reshare permission.`,sources:[n,t]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Workspace role`,definition:`One of Admin, Member, Contributor, or Viewer, granting a fixed set of capabilities on every item in one workspace.`,sources:[n,t]},{term:`Control plane vs data plane`,definition:`Control plane permissions (workspace roles, item permissions) govern what you can do with items; data plane permissions (OneLake security) govern which data you can see or change.`,sources:[i]}],needsVerification:[]},{machineId:`item-locks`,pl300Adds:[{text:`PL-300 covered sharing reports and Build permission on semantic models. Fabric adds data-item permissions: Read lets you connect to a warehouse or endpoint, Read All with SQL analytics endpoint lets you read data with T-SQL, and Read all with Apache Spark lets you read through OneLake and Spark. Item Read alone doesn’t include data access.`,sources:[r,n]}],overview:[{text:`Item permissions give someone access to one item without a workspace role, or add to what a role already allows. Sharing is how you grant them, and the permissions offered depend on the item type.`,sources:[n,r]}],bullets:[{bulletId:`M1.2`,tools:[`workspace`,`lakehouse`,`warehouse`,`semantic-model`],concepts:[{text:`Sharing always grants Read, which lets the recipient find and open the item. Optional extras: Edit, Share (reshare up to your own permissions), Read All with SQL analytics endpoint (ReadData via T-SQL), Read all with Apache Spark (ReadAll via OneLake and Spark), Build (create content on a semantic model), and Execute.`,sources:[r,t]},{text:`Read permission alone shows metadata and reports but not the underlying data in SQL or OneLake. For example, a shared Direct Lake report also needs OneLake data permissions.`,sources:[n]},{text:`To connect to a warehouse or SQL analytics endpoint at all, a user needs a workspace role or item Read. Finer SQL permissions (GRANT/DENY) apply on top of that.`,sources:[oe]}],howTo:[{text:`Select Share on the item, choose the link audience (People in your organization, People with existing access, or Specific people), and tick the extra permissions. Manage permissions on the item lets you review and remove them.`,sources:[r]}]}],examples:[],traps:[{text:`A "People with existing access" link grants nothing. It’s just a URL for people who already have access.`,sources:[r]},{text:`Revoking item permission can take up to two hours to take effect for a signed-in user.`,sources:[r]},{text:`Shared with me only lists Power BI items, not other Fabric items shared with you.`,sources:[r]}],dontConfuse:[{pairId:`access-layers`,a:`Workspace roles vs item permissions`,b:`RLS / CLS / OLS`,difference:[{text:`Workspace roles: coarse, for every item in the workspace, and they define who can do what (control plane). Item permissions: one item, granted by sharing (Read, ReadData, ReadAll, Build, and so on).`,sources:[n,r]},{text:`RLS/CLS/OLS: inside an engine, they narrow which rows, columns, or objects a user who already has access can see. They are set in the warehouse or SQL analytics endpoint (T-SQL), in the semantic model (DAX roles), or in OneLake security roles. T-SQL and semantic model RLS/CLS/OLS only narrow access. OneLake security roles are different: they are Grant roles in a deny-by-default model that give Viewers (or users with item Read) access to the data in the role.`,sources:[n,i]},{text:`Each engine enforces only its own rules. SQL endpoint security applies to SQL queries only, semantic model RLS to the model only, and OneLake security across engines that honor it.`,sources:[fe,n,i]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Item permission`,definition:`A permission on a single Fabric item (such as Read, Edit, Share, ReadData, ReadAll, Build, Execute), usually granted by sharing.`,sources:[r,n]},{term:`Build permission`,definition:`A semantic model permission that lets a user create new content on the model, including reports, Analyze in Excel, and XMLA queries.`,sources:[m,r]},{term:`ReadData / ReadAll`,definition:`Item permissions to read data through the SQL analytics endpoint (ReadData, "Read All with SQL analytics endpoint") or through OneLake and Spark (ReadAll, "Read all with Apache Spark").`,sources:[r,t]}],needsVerification:[]},{machineId:`thread-sieves`,pl300Adds:[{text:`PL-300 covered semantic model RLS roles with DAX filters and group membership. DP-600 adds security in the data layer: T-SQL RLS (security policies with predicate functions), column-level security (GRANT on columns), object-level security (GRANT/DENY on tables and views), dynamic data masking in the warehouse, semantic model OLS, and OneLake security roles for folder- and file-level access.`,sources:[ie,ae,oe,de,i]}],overview:[{text:`Fine-grained security hides rows, columns, objects, or files from users who otherwise have access. Where you define it matters, because each engine enforces its own rules, and some choices make Direct Lake fall back to DirectQuery.`,sources:[n,me]}],bullets:[{bulletId:`M1.3`,tools:[`warehouse`,`sql-analytics-endpoint`,`semantic-model`,`onelake`,`lakehouse`],concepts:[{text:`Warehouse/endpoint RLS: an inline table-valued function returns a row when access is allowed, and CREATE SECURITY POLICY ... ADD FILTER PREDICATE binds it to a table. Rows are silently filtered for SELECT, UPDATE, and DELETE, even for dbo.`,sources:[ie]},{text:`Column-level security: GRANT SELECT on a list of columns. A query that touches a denied column fails with a permission error instead of returning nulls.`,sources:[ae]},{text:`Object-level security in the warehouse: GRANT, REVOKE, and DENY on schemas, tables, and views. You can’t run CREATE USER; the database user is created on GRANT/DENY.`,sources:[oe]},{text:`Semantic model RLS: roles with DAX filter expressions (static, or dynamic with USERPRINCIPALNAME()). Members are assigned in the service. Semantic model OLS: in a role, set a table’s or column’s metadataPermission to none (with TMDL view or Tabular Editor) to hide it completely.`,sources:[ue,de]},{text:`File-level (OneLake security): roles defined on an item grant read access to selected folders, tables, or schemas, optionally with row and column constraints. It is deny-by-default with Grant-only roles, and it is enforced consistently across engines.`,sources:[i,ce]}],howTo:[{text:`Warehouse: create a schema for security objects, the predicate function, then the security policy WITH (STATE = ON). On a SQL analytics endpoint you can’t create tables, but you can create the schema, function, and policy.`,sources:[ie]},{text:`Semantic model: Modeling > Manage roles > New role, write the DAX filter, publish, add members on the model’s Security page in the service, then validate with Test as role.`,sources:[ue]},{text:`OneLake: on the lakehouse, manage OneLake security roles, choose the tables or folders, and assign users, groups, or a workspace-role-based assignment.`,sources:[n,ce]}]}],examples:[{title:`Row-level security in a warehouse`,language:`tsql`,illustrative:!0,steps:[{code:`CREATE SCHEMA Security;`,explain:`Keep security objects in their own schema.`},{code:`CREATE FUNCTION Security.tvf_securitypredicate(@SalesRep AS varchar(100))
    RETURNS TABLE
WITH SCHEMABINDING
AS
    RETURN SELECT 1 AS result
    WHERE @SalesRep = USER_NAME() OR USER_NAME() = 'manager@contoso.com';`,explain:`The predicate returns a row (allow) when the row’s SalesRep is the signed-in user, or when the manager is querying.`},{code:`CREATE SECURITY POLICY SalesFilter
ADD FILTER PREDICATE Security.tvf_securitypredicate(SalesRep)
ON sales.Orders
WITH (STATE = ON);`,explain:`Bind the predicate to sales.Orders as a filter predicate and switch the policy on. Every query on the table is now filtered per user.`}],sources:[ie]},{title:`Column-level and object-level security`,language:`tsql`,illustrative:!0,steps:[{code:`GRANT SELECT ON dbo.Customers (CustomerID, FirstName, LastName, Phone, Email) TO [Charlie@contoso.com];`,explain:`Charlie can read every listed column but not CreditCard; SELECT * fails with a permission error.`},{code:`DENY SELECT ON dbo.Payroll TO [Analysts];`,explain:`Object-level: block a whole table for a group (for example, Viewers who read through SQL).`}],sources:[ae,oe]},{title:`Dynamic RLS in a semantic model`,language:`dax`,illustrative:!0,steps:[{code:`[UserEmail] = USERPRINCIPALNAME()`,explain:`Role filter on a user-mapping table: each signed-in user sees only rows matching their email, and the filter flows to related tables through relationships.`}],sources:[ue]}],traps:[{text:`SQL RLS and views on the SQL analytics endpoint make Direct Lake on SQL fall back to DirectQuery (How Direct Lake works also lists dynamic data masking). For SQL OLS and CLS, Learn pages differ: How Direct Lake works lists OLS as a fallback cause, while Integrate Direct Lake security says queries that touch OLS- or CLS-restricted objects return an error. Direct Lake on OneLake doesn’t check SQL-based security at all; Learn pages differ on whether such a query succeeds or returns an error.`,sources:[me,pe,he,ae]},{text:`SQL security on a SQL analytics endpoint only applies to SQL queries. The same data read through Spark is not filtered by it.`,sources:[fe]},{text:`Semantic model RLS and OLS don’t apply to workspace Admins, Members, or Contributors.`,sources:[ue,de]},{text:`OneLake security roles that grant ReadWrite can’t also contain RLS or CLS constraints.`,sources:[ce]},{text:`Don’t assume a release status Learn doesn’t state. The OneLake security pages mark only enforcement in authorized third-party engines (and its integrations overview) as preview; they don’t call OneLake security as a whole generally available.`,sources:[i,le]},{text:`To change an RLS predicate function, drop the security policy first, alter the function, then recreate the policy.`,sources:[ie]},{text:`Dynamic data masking only obscures values in results. It isn’t access control on its own; Learn says to combine it with CLS and RLS.`,sources:[se]}],dontConfuse:[{pairId:`cls-vs-ols-vs-ddm`,a:`CLS vs semantic model OLS`,b:`Dynamic data masking`,difference:[{text:`Warehouse CLS denies a column, so queries that touch it fail. Semantic model OLS hides a table or column from a role entirely (its metadata too), and visuals report the field can’t be found. Dynamic data masking returns the column but with masked values to non-privileged users.`,sources:[ae,de,se]}]}],renamed:[],preview:[{feature:`OneLake security enforcement in authorized third-party engines`,note:`Learn labels enforcement in authorized third-party engines, and the OneLake security integrations overview, as preview.`,sources:[i,le]}],upcoming:[],glossary:[{term:`Row-level security (RLS)`,definition:`Restricts which rows a user can see: in a warehouse with security policies and predicate functions, or in a semantic model with DAX role filters.`,sources:[ie,ue]},{term:`Column-level security (CLS)`,definition:`Restricts which columns a user can query, granted with GRANT SELECT on column lists in a warehouse or SQL analytics endpoint.`,sources:[ae]},{term:`Object-level security (OLS)`,definition:`Hides whole tables or columns. In a semantic model through role metadataPermission; in a warehouse through GRANT/DENY on objects.`,sources:[de,oe]},{term:`Security policy`,definition:`A T-SQL object (CREATE SECURITY POLICY) that binds a predicate function to tables to enforce row-level security.`,sources:[ie]},{term:`OneLake security role`,definition:`A data-plane role on a Fabric item that grants read (or read-write) access to selected folders, tables, or schemas, optionally with row and column limits.`,sources:[i,ce]},{term:`Dynamic data masking`,definition:`A warehouse feature that masks sensitive column values in query results for non-privileged users without changing stored data.`,sources:[se]},{term:`USERPRINCIPALNAME()`,definition:`A DAX function returning the signed-in user’s UPN (usually their email), used in dynamic RLS filters.`,sources:[ue]}],needsVerification:[]},{machineId:`seal-and-stamp`,pl300Adds:[{text:`You applied sensitivity labels and promoted or certified content in PL-300. Fabric extends both to almost every item type (Power BI dashboards can’t be endorsed). Labels propagate downstream through lineage, and there is a third endorsement badge, Master data, for authoritative data items.`,sources:[a,o]}],overview:[{text:`Sensitivity labels classify and can protect data (from Microsoft Purview Information Protection). Endorsement signals quality and trust so people find the right items. Both are governance signals, but they answer different questions: "how sensitive?" vs "how trustworthy?"`,sources:[a,o]}],bullets:[{bulletId:`M1.4`,tools:[`workspace`,`admin-portal`,`semantic-model`,`power-bi-desktop`],concepts:[{text:`Labels come from Microsoft Purview. Applying them to Power BI items needs a Pro or PPU license plus the Purview licensing, and the label must be published to the user.`,sources:[a]},{text:`Capabilities: manual labeling (all items), default labeling, mandatory labeling (fully for Power BI items, partly for others), programmatic labeling with admin REST APIs, downstream inheritance (all items, with limitations), inheritance from data sources (semantic models only), and labels that follow supported exports.`,sources:[a]},{text:`Protection travels with Excel, PDF, and PowerPoint exports and with .pbix downloads, but not with other paths such as CSV export or cross-tenant sharing.`,sources:[a]}],howTo:[{text:`Label items manually (supported for all Fabric items), or rely on default, mandatory, and inherited labeling. Labels can also be managed programmatically through the admin REST APIs. Use the OneLake catalog’s governance experiences to monitor label coverage and find unlabeled items.`,sources:[a]}]},{bulletId:`M1.5`,tools:[`workspace`,`admin-portal`],concepts:[{text:`Promoted: the creator says the item is ready to share. Any user with write permission can promote any item except dashboards.`,sources:[o]},{text:`Certified: an authorized reviewer confirms the item meets organizational standards. Anyone can request certification, but only users the Fabric admin specifies can certify.`,sources:[o]},{text:`Master data: the item is the authoritative source for core data such as customer lists. It applies only to items that contain data, such as lakehouses and semantic models, and only admin-specified users can apply it.`,sources:[o]}],howTo:[{text:`Follow Learn’s promote, certify, and master data procedures for the item. Certification and master data must first be enabled by a Fabric admin, and certification can be delegated to domain admins so each domain has its own reviewers.`,sources:[o]}]}],examples:[],traps:[{text:`Endorsed items get a badge and are listed first in some lists, to help people find trusted content.`,sources:[o]},{text:`Power BI dashboards can’t be promoted or certified.`,sources:[o]},{text:`Label access control only works in the tenant where it was applied, for .pbix files, and for supported exports. Cross-tenant scenarios and CSV/TXT exports aren’t protected.`,sources:[a]}],dontConfuse:[{pairId:`endorse-vs-label`,a:`Endorsement (promoted / certified / master data)`,b:`Sensitivity label`,difference:[{text:`Endorsement says how trustworthy or authoritative an item is, to help discovery. It is set in Fabric to help people find trusted content. A sensitivity label says how sensitive the data is. It comes from Microsoft Purview, can enforce encryption and access through protection policies, propagates downstream, and follows supported exports.`,sources:[o,a]},{text:`Who can apply: promote = anyone with write permission; certify and master data = admin-designated users; labels = users included in the tenant setting who also have the label published to them.`,sources:[o,a]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Sensitivity label`,definition:`A Microsoft Purview classification (such as Confidential) applied to an item. It can carry protection policies and propagate to downstream items and supported exports.`,sources:[a]},{term:`Downstream inheritance`,definition:`When a label applied to an item automatically propagates to items that depend on it.`,sources:[a]},{term:`Endorsement`,definition:`A Fabric badge marking an item as Promoted, Certified, or Master data to help people find trustworthy content.`,sources:[o]},{term:`Master data`,definition:`An endorsement for data items that are the authoritative single source of truth for core business data.`,sources:[o]}],needsVerification:[]},{machineId:`pattern-ledger`,overview:[{text:`Git integration connects a Fabric workspace to a branch in Azure DevOps or GitHub, so item definitions are versioned, can be reverted, and can be developed on branches. It is the source-control half of Fabric’s lifecycle tools.`,sources:[ge]}],bullets:[{bulletId:`M2.1`,tools:[`workspace`],concepts:[{text:`Supported providers: Azure DevOps, GitHub, and GitHub Enterprise, all cloud-based only. Integration is at workspace level, and folder structure (up to 10 levels) is mirrored in the repo.`,sources:[ge,s]},{text:`Only a workspace Admin can connect or disconnect the workspace. After that, Members and Contributors can commit and update according to their Git permissions. Each user configures their own Git account connection.`,sources:[s]},{text:`Git status per item: Synced, Conflict, Uncommitted changes, Update required, or Unsupported. Commit sends workspace changes to Git; Update brings Git changes into the workspace.`,sources:[s]},{text:`Not every item is supported. Learn keeps a list, and some entries (including semantic models) are marked preview.`,sources:[ge]}],howTo:[{text:`Your organization’s admin must first enable Git integration. Then a workspace Admin connects the workspace to a repository branch (and folder). The connected branch can later be changed from the workspace settings dialog.`,sources:[s]},{text:`Initial sync: if one side is empty, content copies to it. If both sides have content, choose a direction. Committing overwrites Git; updating overwrites the workspace, which is why Fabric asks you to confirm.`,sources:[s]},{text:`Use the Source control pane to commit and update. Use branch out or checkout to work on a new branch, then merge through your Git provider’s pull requests.`,sources:[s]}]}],examples:[],traps:[{text:`Updating the workspace from Git when both sides have content overwrites the workspace. A Git branch can be restored to an earlier commit, but the workspace can’t.`,sources:[s]},{text:`Members and Contributors can switch the connected branch only if an Admin enables "Allow users with at least Contributor role to change Git branch".`,sources:[s]},{text:`Empty folders aren’t copied to Git.`,sources:[s]}],dontConfuse:[{pairId:`commit-vs-update`,a:`Commit`,b:`Update`,difference:[{text:`Commit pushes workspace changes into the connected Git branch. Update pulls the branch’s latest commit into the workspace. The Git status column shows which one each item needs.`,sources:[s]}]}],renamed:[],preview:[{feature:`Git integration for semantic models`,note:`Listed with "(preview)" in Learn’s Git supported-items list (excluding push datasets, live connections to Analysis Services, and model v1).`,sources:[ge]}],upcoming:[{date:`2026-12-01`,change:`Users without read-write permissions on workspace items can’t use Git integration. Sensitivity labels and protection policies on items can result in loss of access to certain items.`,sources:[s]}],glossary:[{term:`Git integration`,definition:`Fabric’s workspace-level connection to an Azure DevOps or GitHub branch for versioning item definitions.`,sources:[ge]},{term:`Commit (Fabric Git)`,definition:`Saving the workspace’s changed items to the connected Git branch.`,sources:[s]},{term:`Update (Fabric Git)`,definition:`Bringing the latest commit from the connected branch into the workspace, overwriting workspace items.`,sources:[s]},{term:`Branched workspace`,definition:`A workspace created by a Git branch-out that is linked to its source workspace for isolated development.`,sources:[`${e}fabric/fundamentals/workspaces`]}],needsVerification:[]},{machineId:`draft-table`,overview:[{text:`A Power BI Desktop project (.pbip) saves a report and its semantic model as folders of plain-text files instead of one binary .pbix. That makes Power BI work diffable, reviewable, and ready for Git and CI/CD. Windows only: Power BI Desktop requires Windows.`,sources:[c,Ce]}],bullets:[{bulletId:`M2.2`,tools:[`power-bi-desktop`],concepts:[{text:`Saving as a project creates <name>.Report and <name>.SemanticModel folders, a .gitignore, and a <name>.pbip file that just points to the report folder. You can also open the report directly from its definition.pbir.`,sources:[c]},{text:`The generated .gitignore excludes the local data cache (cache.abf) and localSettings.json, so data isn’t committed to source control.`,sources:[c]},{text:`Model metadata is stored as TMDL files in the semantic model’s definition folder, which you can edit in VS Code or other tools.`,sources:[c]}],howTo:[{text:`In Power BI Desktop, save a new or existing report as a project (.pbip) and commit the folder to Git. To publish, use Desktop’s Publish (which sends a temporary .pbix with data) or deploy only the metadata through other mechanisms such as Fabric Git integration.`,sources:[c]}]}],examples:[],traps:[{text:`You can’t save a PBIP directly to OneDrive or SharePoint from Desktop, and saving into a locally synced OneDrive folder can cause sync failures.`,sources:[c]},{text:`The .pbip file is optional. It is only a shortcut to the report folder; the definition files are what matter.`,sources:[c]},{text:`Other deployment paths deploy metadata only. Desktop Publish also sends the local data cache.`,sources:[c]}],dontConfuse:[],renamed:[],preview:[],upcoming:[],glossary:[{term:`Power BI project (.pbip)`,definition:`A Power BI Desktop save format that stores report and semantic model definitions as plain-text files in folders, designed for source control.`,sources:[c]},{term:`TMDL`,definition:`Tabular Model Definition Language: the text format of semantic model metadata in a .pbip project. Also used in Desktop’s TMDL view.`,sources:[c,we]}],needsVerification:[]},{machineId:`conveyor`,overview:[{text:`Deployment pipelines move content through stages (by default Development, Test, Production) inside the Fabric service, so you can test before users see changes. They are the release half of the lifecycle tools, alongside Git integration for version control.`,sources:[l,_e]}],bullets:[{bulletId:`M2.3`,tools:[`workspace`],concepts:[{text:`A pipeline has 2 to 10 stages, set when it is created and fixed afterwards. Each stage is assigned one workspace (on a capacity).`,sources:[_e]},{text:`Deploying copies item definitions (metadata) from one stage to the next, keeps links between items, and overwrites the paired items in the target. Data isn’t copied between stages: after a first deployment, refresh semantic models; on later deployments, data in the target is kept when possible.`,sources:[u]},{text:`Deployment rules change settings per stage: data source rules, parameter rules, and default lakehouse rules for notebooks. For example, production points at the production database.`,sources:[ve]},{text:`An optional deployment plan (preview) adds ordering and pre- or post-deployment actions.`,sources:[l]},{text:`Pipelines have only one permission, Admin, and it grants no access to workspace content. What you can do inside a stage comes from your workspace role there, so pipeline admin and workspace roles are managed separately.`,sources:[u]},{text:`Autobinding: a deployed item reconnects to the item it depends on in the target stage (for example a report to the target stage’s semantic model). A Direct Lake semantic model is the exception: it stays bound to the source stage’s lakehouse until you add a datasource rule.`,sources:[u]}],howTo:[{text:`Create the pipeline (you need to be a workspace admin), name the stages, and assign a workspace to a stage. Compare stages, then deploy all or selected items to the next stage. Rules are defined on the target stage and take effect on the next deployment.`,sources:[_e,ve]},{text:`Permissions per action: deploy between stages = pipeline admin + at least Contributor on both the source and target workspaces. Deploy to an empty stage = pipeline admin + Contributor on the source workspace. Assign a workspace to a stage = pipeline admin + Admin of that workspace. Nuance: the same page’s “Granted permissions” table lists workspace Member as the permission to deploy an existing semantic model or paginated report, and dataflow owner for dataflows. The two tables differ for semantic models and paginated reports, so this app doesn’t test a Contributor deploying those.`,sources:[u]}]}],examples:[],traps:[{text:`A deployment fails if an item depends on another item that isn’t in the target stage and isn’t being deployed (for example a report without its semantic model).`,sources:[u]},{text:`A Direct Lake semantic model doesn’t autobind to the target stage’s lakehouse. After deployment it still reads the source stage’s lakehouse until you add a datasource rule. Other semantic models autobind to items in the target stage.`,sources:[u]},{text:`Being a pipeline admin alone doesn’t let you see or deploy content. You also need a workspace role in the stages involved.`,sources:[u]},{text:`Data source rules only work when switching between data sources of the same type.`,sources:[ve]},{text:`Since February 12, 2026, deployment pipelines no longer support semantic models that haven’t been upgraded to Enhanced Metadata.`,sources:[l]},{text:`A Data Factory pipeline (data movement) is unrelated to a deployment pipeline (lifecycle).`,sources:[`${e}fabric/fundamentals/fabric-terminology`]}],dontConfuse:[{pairId:`pipelines-vs-git`,a:`Deployment pipelines`,b:`Git integration`,difference:[{text:`Git integration is version control: a workspace syncs with a branch for history, branching, and reverting. Deployment pipelines are release management: they copy content between stage workspaces (Dev → Test → Prod) inside Fabric, applying rules per stage.`,sources:[ge,l]},{text:`They’re independent. Deployment pipelines don’t require Git (Learn’s pipeline docs point to Git separately for version control).`,sources:[l]},{text:`Permissions differ: connecting Git needs the workspace Admin role; creating a deployment pipeline needs you to be a workspace admin, and sharing the pipeline makes others pipeline admins.`,sources:[s,_e]}]}],renamed:[],preview:[{feature:`New deployment pipelines user interface`,note:`The new UI is in preview, and some deployable item types are preview too.`,sources:[l]}],upcoming:[{date:`2026-12-01`,change:`Users without read-write permissions on all workspace items can’t deploy to a workspace, or assign it to certain stages, when it contains items protected by sensitivity labels with protection policies.`,sources:[u]}],glossary:[{term:`Deployment pipeline`,definition:`A Fabric lifecycle tool with 2 to 10 stages, each backed by a workspace, used to promote content from development to production.`,sources:[l,_e]},{term:`Deployment rule`,definition:`A per-stage setting (data source, parameter, or default lakehouse) that changes an item’s configuration when content is deployed to that stage.`,sources:[ve]},{term:`Paired items`,definition:`Items in different pipeline stages linked as the same content. Deployment overwrites the paired item in the target stage.`,sources:[u]}],contested:[{topic:`Which workspace role can deploy an existing semantic model or paginated report`,readings:[{text:`Understand the deployment process, permissions table: a workspace contributor who is also a pipeline admin can "Deploy items (must be at least a contributor in both source and target workspaces)".`,sources:[u]},{text:`The same page’s "Granted permissions" table lists "Workspace member" as the required permission to deploy an existing semantic model or paginated report.`,sources:[u]}],guidance:`The two tables on one page don’t agree for these item types, so no question or puzzle asks whether a Contributor can deploy them. The page’s general rule still holds: to deploy you must be a pipeline admin and a contributor, member, or admin of the workspaces in the stages involved.`}],needsVerification:[]},{machineId:`ripple-map`,overview:[{text:`Before you change a lakehouse table, a warehouse, a dataflow, or a semantic model, find out what depends on it. Lineage view shows how items connect, and impact analysis lists every downstream item and workspace a change could break, with a way to warn their owners.`,sources:[ye,d]}],bullets:[{bulletId:`M2.4`,tools:[`workspace`,`lakehouse`,`warehouse`,`dataflow-gen2`,`semantic-model`],concepts:[{text:`Lineage view (one per workspace) shows every item in the workspace and how they connect, plus upstream sources one level outside the workspace. Downstream items in other workspaces aren’t shown there.`,sources:[ye]},{text:`Impact analysis shows direct children or all downstream items, including those in other workspaces, grouped by type or by workspace. For data sources it shows only direct children and the connection string.`,sources:[d]},{text:`Notify contacts emails the contact lists of all affected workspaces, even ones you can’t access.`,sources:[d]}],howTo:[{text:`Open impact analysis from the item’s card in lineage view or from Lineage on the item’s details page. Switch between Child items and All downstream items, then select Notify contacts and describe the change.`,sources:[d]}]}],examples:[],traps:[{text:`You need write permission on an item to run impact analysis on it. Items you can’t access appear as "Limited access".`,sources:[d]},{text:`Viewers can open lineage view but don’t see data sources.`,sources:[ye]},{text:`To see downstream dependencies outside the current workspace, use impact analysis, not lineage view.`,sources:[ye]}],dontConfuse:[{pairId:`lineage-vs-impact`,a:`Lineage view`,b:`Impact analysis`,difference:[{text:`Lineage view is a workspace-wide diagram of how items connect (plus upstream sources one level out). Impact analysis starts from one item and lists everything downstream, across workspaces, with counts and a notify option.`,sources:[ye,d]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Lineage view`,definition:`A workspace view showing the items in the workspace and the data flow between them, including upstream sources one level outside.`,sources:[ye]},{term:`Impact analysis`,definition:`A pane listing an item’s direct or all downstream dependents across workspaces, with an option to notify their contacts.`,sources:[d]},{term:`Workspace contact list`,definition:`The users or groups notified about issues in a workspace. Impact analysis notifications go to these lists.`,sources:[re,d]}],needsVerification:[]},{machineId:`remote-loom-control`,overview:[{text:`The XMLA endpoint exposes semantic models in a capacity workspace with the same protocol as Analysis Services. That lets enterprise tools query, script, deploy, and refresh models outside Power BI Desktop, for example SSMS, Tabular Editor, Visual Studio, ALM Toolkit, and PowerShell.`,sources:[f]}],bullets:[{bulletId:`M2.5`,tools:[`semantic-model`,`admin-portal`,`workspace`],concepts:[{text:`Read-only XMLA is on by default for the capacity’s semantic models workload. Writing (deploying, changing metadata, TMSL scripting) needs the capacity’s XMLA Endpoint setting set to Read Write, which applies to all workspaces on the capacity.`,sources:[f]},{text:`Workspace Contributors and above have Write permission on semantic models over XMLA, which is effectively Analysis Services database admin.`,sources:[f]},{text:`Each capacity workspace has a connection URL: powerbi://api.powerbi.com/v1.0/[tenant]/[workspace name].`,sources:[f]},{text:`TMSL refresh types include full (refresh data and recalculate dependents), dataOnly, calculate, and automatic (refresh only what needs it). TMSL refresh can also override an incremental refresh policy.`,sources:[be]}],howTo:[{text:`Enable read-write: in the admin portal’s capacity settings, expand Workloads (or the semantic model workload settings for PPU) and set XMLA Endpoint to Read Write.`,sources:[f]},{text:`Copy the URL from Workspace settings > Premium > Workspace Connection, paste it as the server in SSMS or Tabular Editor, or as the Deployment Server in a Visual Studio tabular project.`,sources:[f]},{text:`Turn on the large semantic model storage format for models you manage through XMLA, because it improves XMLA write performance.`,sources:[xe]}]}],examples:[{title:`Refresh one table over XMLA with TMSL`,language:`tmsl`,illustrative:!0,steps:[{code:`{
  "refresh": {
    "type": "full",
    "objects": [
      { "database": "SalesModel", "table": "FactSales" }
    ]
  }
}`,explain:`Run in SSMS connected to the workspace’s XMLA URL. It fully refreshes the FactSales table (reload data and recalculate dependents) in the SalesModel semantic model.`}],sources:[be,f]}],traps:[{text:`Semantic models in Pro workspaces don’t support XMLA write operations. You need a capacity or PPU.`,sources:[xe,f]},{text:`Read-only is the default. If a deployment from Tabular Editor or Visual Studio fails, check the capacity’s XMLA Endpoint setting.`,sources:[f]}],dontConfuse:[{pairId:`xmla-read-vs-readwrite`,a:`XMLA read-only`,b:`XMLA read-write`,difference:[{text:`Read-only (default) lets tools query data, metadata, events, and schema: Excel, DAX Studio, Report Builder, SSMS queries. Read-write adds metadata changes and deployment: SSMS TMSL scripting, Tabular Editor saves, the Visual Studio deployment wizard, ALM Toolkit deploys, and PowerShell refresh.`,sources:[f]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`XMLA endpoint`,definition:`An Analysis Services-compatible endpoint on capacity workspaces that client tools use to query and manage semantic models.`,sources:[f]},{term:`TMSL`,definition:`Tabular Model Scripting Language: JSON commands (such as refresh, createOrReplace, alter, delete) sent over XMLA to manage tabular models.`,sources:[be,ne,f]},{term:`Workspace connection URL`,definition:`The powerbi:// address of a capacity workspace used as the server name by XMLA tools.`,sources:[f]}],needsVerification:[]},{machineId:`pattern-book`,pl300Adds:[{text:`PL-300 covered connecting to shared semantic models. DP-600 adds packaging reuse: .pbit templates (report plus model plus queries without data), .pbids files (a ready-made data connection), and managing shared models with Build permission, endorsement, and cross-workspace reuse. .pbit and .pbids are created in Power BI Desktop, which is Windows only.`,sources:[p,Se,m,Ce]}],overview:[{text:`Reusable assets stop teams rebuilding the same model or connection. One certified shared semantic model serves many reports. A template gives authors a standard starting layout and model. A .pbids file gives beginners a one-click connection.`,sources:[m,p,Se]}],bullets:[{bulletId:`M2.6`,tools:[`power-bi-desktop`,`semantic-model`,`workspace`],concepts:[{text:`.pbit (Power BI template): contains report pages and visuals, the data model definition, and all queries and parameters, but no data. Opening it prompts for parameter values and data source credentials.`,sources:[p]},{text:`.pbids (Power BI data source file): a small JSON file describing one data source connection (protocol, address, optional DirectQuery or Import mode). Opening it prompts for credentials and opens Navigator to pick tables. It holds no credentials and no table list.`,sources:[Se]},{text:`Shared semantic models: one model reused by reports in many workspaces. Build permission controls who can create content on it, and promotion or certification helps people find it.`,sources:[m]}],howTo:[{text:`Create a template: File > Export > Power BI template, then add a description. Use it by double-clicking the .pbit or with File > Import > Power BI template.`,sources:[p]},{text:`Create a .pbids: File > Options and settings > Data source settings, select the source, then Export PBIDS. Or write the JSON by hand.`,sources:[Se]},{text:`Share a model: grant Build permission, endorse it, and let authors connect from the OneLake catalog or Get data in Desktop.`,sources:[m,o]}]}],examples:[],traps:[{text:`A .pbids file supports only one data source; listing more causes an error.`,sources:[Se]},{text:`A .pbit has no data, but filter values saved in report metadata (for example Company = "Contoso") remain in the file.`,sources:[p]},{text:`Users with only a free license can build reports from shared models (with Build permission) only when the model is on Premium or an F64-or-larger capacity. Copying reports between workspaces needs Pro or PPU.`,sources:[m]}],dontConfuse:[{pairId:`pbi-files`,a:`.pbix vs .pbip`,b:`.pbit vs .pbids`,difference:[{text:`.pbix: a single Power BI Desktop report file with the model and data. .pbip: a project folder of plain-text report and model definitions (TMDL), with the local data cache git-ignored, built for source control.`,sources:[p,c]},{text:`.pbit: a template with report, model, and queries but no data, used as a starting point. .pbids: only a data source connection (JSON) that opens Get data for that source.`,sources:[p,Se]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`.pbix`,definition:`The standard Power BI Desktop report file, containing report, model, and imported data in one file.`,sources:[p]},{term:`Power BI template (.pbit)`,definition:`A Power BI Desktop file containing report pages, model definition, and queries but no data, used as a starting point for new reports.`,sources:[p]},{term:`Power BI data source file (.pbids)`,definition:`A JSON file describing a single data source connection that opens Power BI Desktop’s Get data for that source.`,sources:[Se]},{term:`Shared semantic model`,definition:`A semantic model reused by reports in other workspaces, controlled with Build permission and usually endorsed.`,sources:[m]}],needsVerification:[]}],h=`https://learn.microsoft.com/en-us/`,g=`${h}fabric/fundamentals/microsoft-fabric-overview`,_=`${h}fabric/fundamentals/fabric-terminology`,Ee=`${h}fabric/onelake/onelake-overview`,v=`${h}fabric/enterprise/licenses`,De=`${h}fabric/fundamentals/workspaces`,Oe=`${h}fabric/fundamentals/roles-workspaces`,ke=`${h}fabric/enterprise/throttling`,y=`${h}fabric/fundamentals/fabric-trial`,Ae=`${h}fabric/fundamentals/decision-guide-data-store`,b=`${h}fabric/data-engineering/lakehouse-overview`,je=`${h}fabric/data-warehouse/data-warehousing`,Me=`${h}fabric/real-time-intelligence/eventhouse`,Ne=`${h}fabric/onelake/onelake-medallion-lakehouse-architecture`,Pe=`${h}power-bi/fundamentals/desktop-get-the-desktop`,Fe=`${h}credentials/certifications/resources/study-guides/dp-600`,Ie=`${h}fabric/cicd/deployment-pipelines/intro-to-deployment-pipelines`,Le=`${h}fabric/real-time-intelligence/overview`,Re=[{machineId:`founding-charter`,overview:[{text:`Microsoft Fabric is one analytics platform for the whole data journey: getting data in, transforming it, processing streams, analyzing it, and reporting on it. It is sold as software as a service, so there are no servers or Azure resources for you to manage.`,sources:[g]},{text:`Fabric is split into workloads, each aimed at a role: Data Factory (data integration), Data Engineering (Apache Spark and notebooks), Data Warehouse (T-SQL), Data Science (machine learning), Real-Time Intelligence (streaming and event data), Databases (transactional SQL and Cosmos DB), Industry Solutions, Fabric IQ, and Power BI.`,sources:[g,_]},{text:`Every workload shares the same storage layer, OneLake, and the same compute model. A table written by one engine (for example a warehouse using T-SQL) can be read by another (for example a Spark notebook) without copying it.`,sources:[g,Ee]},{text:`Why it matters for an analytics engineer: the DP-600 skills outline spans these workloads. You prepare data with Data Factory, Spark, or T-SQL, store it in a lakehouse, warehouse, or eventhouse, and serve it to Power BI through a semantic model. Knowing which workload owns which item is the first step.`,sources:[g,_,Fe]},{text:`The objects you create inside a workspace, such as a lakehouse, notebook, warehouse, eventhouse, report, or semantic model, are called items. Items live in workspaces, and each workload provides its own item types.`,sources:[_]}],bullets:[],examples:[],traps:[{text:`Fabric IQ is labelled Preview on Learn and is not part of the DP-600 skills outline. Know it exists, but don’t expect it to be the focus of questions.`,sources:[g,Fe]},{text:`Learn says you don’t need an Azure account to use Fabric. OneLake hides storage details like resource groups and regions.`,sources:[g]},{text:`A data pipeline (a Data Factory item that orchestrates data movement) is not the same thing as a deployment pipeline (the lifecycle tool that promotes content between stages). Learn calls this out directly.`,sources:[_,Ie]}],dontConfuse:[{pairId:`workload-vs-item`,a:`Workload`,b:`Item`,difference:[{text:`A workload is a group of capabilities for one kind of work, such as Data Engineering. An item is a concrete object you create inside a workspace, such as a lakehouse or notebook. A workload provides several item types.`,sources:[_]}]}],renamed:[],preview:[{feature:`Fabric IQ`,note:`A workload for unifying business semantics (ontology, planning, Fabric Graph, data agents). Labelled "(preview)" on the Fabric overview page.`,sources:[g]}],upcoming:[],glossary:[{term:`Microsoft Fabric`,definition:`A software-as-a-service analytics platform that covers ingestion, transformation, real-time processing, analytics, and reporting over shared storage (OneLake).`,sources:[g]},{term:`Workload`,definition:`A collection of Fabric capabilities aimed at one kind of work, for example Data Engineering, Data Factory, Data Warehouse, Real-Time Intelligence, or Power BI.`,sources:[_]},{term:`Item`,definition:`An object you create in Fabric, such as a lakehouse, notebook, warehouse, eventhouse, report, or semantic model.`,sources:[_]},{term:`Delta Lake`,definition:`The standard table format across Fabric workloads. Data ingested into Fabric is stored as Delta tables by default (Parquet files plus a transaction log).`,sources:[_,je]}],needsVerification:[]},{machineId:`water-wheel`,overview:[{text:`Three platform concepts sit under every Fabric item: OneLake (where data is stored), capacities (the compute you pay for), and workspaces (where items are organized and secured).`,sources:[Ee,v]},{text:`OneLake is one data lake for the whole organization. Each tenant gets exactly one, created automatically; you can’t delete it or create a second one. It is built on Azure Data Lake Storage Gen2 and stores tables in open formats (Delta Parquet or Iceberg).`,sources:[Ee]},{text:`Data is organized in a hierarchy: tenant at the root, then workspaces (like folders), then items such as lakehouses, warehouses, and eventhouses. Fabric domains can group workspaces into business areas above that.`,sources:[Ee,_]},{text:`A capacity is a pool of compute in your tenant. Its size, measured in capacity units (CUs), sets how much compute is available. Fabric capacities are F SKUs bought through Azure and billed per second. Older Power BI Premium P SKUs also run Fabric, but Microsoft is retiring them.`,sources:[v,_]},{text:`A workspace is a container for items that runs on a capacity and controls who can access its contents. Access is granted through four workspace roles: Admin, Member, Contributor, and Viewer. Every user also has a personal My workspace.`,sources:[De,Oe,v]},{text:`Why it matters: storage location, compute cost, and access all depend on these three, so know which workspace and capacity an item sits in.`,sources:[v]}],bullets:[],examples:[],traps:[{text:`To view Power BI content with only a free Fabric license, the workspace must be on an F64 or larger capacity and you need the Viewer role. On F SKUs smaller than F64, every viewer of Power BI content needs Pro, PPU, or an individual trial license.`,sources:[v]},{text:`A Power BI Premium Per User (PPU) workspace is not a Fabric capacity. It can’t create non-Power BI Fabric items such as lakehouses unless an F capacity is also involved.`,sources:[v]},{text:`Creating Power BI items in a workspace other than My workspace needs a Power BI Pro or Premium Per-User (PPU) license, or a Power BI individual trial, even on a capacity.`,sources:[v]},{text:`Capacity overload doesn’t throttle immediately. Fabric bursts and smooths usage: interactive operations are smoothed over 5 to 64 minutes and background operations over 24 hours. Throttling escalates in stages: delays first, then interactive rejection, then all requests are rejected.`,sources:[ke]},{text:`Throttling applies per capacity. One overloaded capacity doesn’t slow workspaces on other capacities.`,sources:[ke]}],dontConfuse:[{pairId:`capacity-vs-workspace`,a:`Capacity`,b:`Workspace`,difference:[{text:`A capacity is compute (CUs) you buy and that gets throttled. A workspace is a container for items and access roles. A workspace is assigned to one capacity, and a capacity can host many workspaces.`,sources:[v,Ee]}]}],renamed:[{oldName:`License mode`,newName:`Workspace type`,examLikely:`Unclear. The DP-600 study guide uses neither term, so recognize both. Current Learn pages say "workspace type".`,note:`Learn states this is a terminology change only; functionality is the same.`,sources:[v,Fe]}],preview:[],upcoming:[],glossary:[{term:`OneLake`,definition:`The single, tenant-wide logical data lake in Fabric, built on Azure Data Lake Storage Gen2. Every workload stores and reads its data there.`,sources:[Ee]},{term:`Tenant`,definition:`One instance of Fabric for an organization, aligned with a Microsoft Entra tenant. It maps to the root of OneLake.`,sources:[_,g]},{term:`Capacity`,definition:`A dedicated pool of compute in a tenant. Workspaces are assigned to a capacity, and the capacity size sets how much work they can run.`,sources:[v,_]},{term:`Capacity unit (CU)`,definition:`The unit of compute in Fabric. Every operation consumes CUs from the capacity. Consumption is classed as interactive or background.`,sources:[_]},{term:`F SKU`,definition:`A Fabric capacity size bought through Azure (F2 up to F8192), billed per second with no commitment. Learn recommends F SKUs for Fabric.`,sources:[v]},{term:`Workspace`,definition:`A collaboration container for items that runs on a capacity and controls access through roles (Admin, Member, Contributor, Viewer).`,sources:[_,Oe]},{term:`Domain`,definition:`A grouping of workspaces into a business area (such as Finance) so admins can delegate management and apply governance above the workspace level.`,sources:[_]},{term:`Smoothing`,definition:`Fabric spreads an operation’s CU usage over future 30-second timepoints (minutes for interactive work, 24 hours for background work) so short spikes don’t cause throttling.`,sources:[ke]},{term:`Throttling`,definition:`What a capacity does when it has used up future CUs: first it delays interactive operations, then it rejects them, then it rejects all new requests.`,sources:[ke]}],needsVerification:[]},{machineId:`three-vats`,overview:[{text:`Fabric has several places to store analytical data. The DP-600 outline names three: the lakehouse, the warehouse, and the eventhouse. All three keep their data in OneLake. They differ in how you write to them, how you query them, and what kind of data they suit.`,sources:[Ae]},{text:`A lakehouse combines a data lake with SQL querying. It holds structured and unstructured data as files and Delta tables. You build it mainly with Apache Spark (notebooks), and every lakehouse gets a read-only SQL analytics endpoint for T-SQL queries.`,sources:[b]},{text:`A warehouse is a relational data warehouse developed with T-SQL. It has full DDL and DML support and multi-table ACID transactions. It suits star or snowflake schemas and curated data marts for BI.`,sources:[je]},{text:`An eventhouse is built for streaming, time-based event data such as telemetry, logs, IoT readings, and time series. It can hold structured, semistructured (JSON, XML), and free-text data, and it contains one or more KQL databases that you query with KQL.`,sources:[Me,_]},{text:`Why it matters: the outline asks you to choose between data stores (Vat Selector) and to implement star schemas, views, and procedures in the right one. Most of these questions come down to what each store can write and query.`,sources:[Ae,Fe]}],bullets:[],examples:[],traps:[{text:`The SQL analytics endpoint of a lakehouse is read-only for data. T-SQL there can define and query objects, but it can’t INSERT, UPDATE, or DELETE. To change lakehouse data, use Spark, pipelines, or dataflows.`,sources:[je,b]},{text:`Only Delta tables show up in the SQL analytics endpoint. Parquet or CSV files in the Files area can’t be queried there until converted to Delta.`,sources:[b]},{text:`Multi-table transactions are a warehouse feature. A lakehouse doesn’t support them.`,sources:[b]},{text:`Lakehouse and warehouse data are in OneLake in Delta format by default. For a KQL database in an eventhouse, OneLake availability is opt-in.`,sources:[Ae]},{text:`Since September 5, 2025, creating a lakehouse no longer creates a default semantic model automatically. Older study material that mentions a "default semantic model" is out of date.`,sources:[b]}],dontConfuse:[{pairId:`stores`,a:`Lakehouse vs warehouse`,b:`Eventhouse`,difference:[{text:`Write: a lakehouse is written by Spark notebooks, pipelines, Dataflow Gen2, and shortcuts. A warehouse is written by T-SQL (COPY INTO, INSERT, CREATE TABLE AS SELECT), pipelines, and dataflows. An eventhouse ingests from sources such as Eventstream, Kafka, Logstash, SDKs, and dataflows.`,sources:[b,je,Me]},{text:`Query: a lakehouse is queried with Spark (Python, Scala, SQL, R) and read-only T-SQL through its SQL analytics endpoint. A warehouse is queried with full T-SQL. An eventhouse is queried mainly with KQL (T-SQL is also listed).`,sources:[b,je,Ae]},{text:`Store: a lakehouse holds structured and unstructured data (tables plus files). A warehouse holds structured tables. An eventhouse holds time-based event data, including semistructured and free text, organized by arrival time.`,sources:[b,Me]},{text:`Best for: lakehouse for data engineering, data science, and medallion architectures. Warehouse for BI reporting, dimensional modeling, and SQL-first teams. Eventhouse for streaming, high-granularity, interactive analytics over events.`,sources:[b,Ae]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Lakehouse`,definition:`A Fabric item that is a database over a data lake: files, folders, and Delta tables, used by both Spark and the SQL engine.`,sources:[_,b]},{term:`Warehouse`,definition:`A Fabric item that works like a traditional data warehouse, with full transactional T-SQL (DDL and DML) over Delta tables in OneLake.`,sources:[_,je]},{term:`Eventhouse`,definition:`A Fabric item for storing and analyzing large volumes of real-time, time-based event data. It contains one or more KQL databases.`,sources:[_,Me]},{term:`KQL database`,definition:`A database inside an eventhouse that holds tables you query with Kusto Query Language (KQL).`,sources:[_]},{term:`SQL analytics endpoint`,definition:`An automatically created, read-only T-SQL surface over Delta tables (for example a lakehouse’s tables). You can create views, inline table-valued functions, and procedures there, and manage permissions, but you can’t modify data.`,sources:[_,je]},{term:`Medallion architecture`,definition:`A three-layer lakehouse design: bronze (raw data, stored as it arrives), silver (enriched: errors fixed, formats standardized, duplicates removed), and gold (curated for reports).`,sources:[Ne,b]}],needsVerification:[]},{machineId:`mill-lease`,overview:[{text:`You learn Fabric fastest by using it. The Fabric trial gives you a free trial capacity for 60 days so you can build lakehouses, warehouses, notebooks, pipelines, and reports for the hands-on labs in Step 6.`,sources:[y]},{text:`The trial capacity is configured as either an F4 (4 capacity units) or an F64 (64 capacity units). If yours is 4 capacity units, a capacity or tenant administrator may be eligible to increase it to 64 (and back down) on the Trial tab of the capacities page; changing the size doesn’t extend the 60 days. It comes with a Power BI individual trial if you don’t already have a Premium Per User license, and it allows up to 1 TB of OneLake storage.`,sources:[y]},{text:`Three ways to start one: start a trial from the Account manager, try to use a Fabric feature (this triggers a trial), or join a coworker’s trial capacity if they give you Contributor permission on it. The first two make you the capacity administrator.`,sources:[y]},{text:`To use it, create a workspace and set its workspace type to Trial. Everything in that workspace then runs on the trial capacity.`,sources:[y]},{text:`Platform note: Power BI Desktop, which some later labs use (for example for .pbip projects), lists Windows 10 or Windows Server 2016 or later in its system requirements. Each lab shows the platform it needs.`,sources:[Pe]}],bullets:[],examples:[],traps:[{text:`Not everything is in the trial: Copilot, Trusted Workspace Access, AI experiences such as data agents and AI functions, and Private Link are unavailable.`,sources:[y]},{text:`When the trial ends, its workspaces revert to Pro, non-Power BI items like notebooks and pipelines become inactive, and content stays in OneLake for 7 days. Reassign the workspace to a paid F or P capacity within that window to keep it.`,sources:[y]},{text:`Pick the trial region carefully. Moving a workspace with Fabric items to another region later means deleting those items first.`,sources:[y]},{text:`If you don’t see "Start trial" in the Account manager, trials may be disabled for your tenant, or you may already have a Power BI individual trial. In that case, try to create a Fabric item to get the trial prompt.`,sources:[y]},{text:`The trial page’s workload list still says "Real-Time Analytics", while the Fabric overview and the workload’s own pages say "Real-Time Intelligence". Expect the current name, Real-Time Intelligence, in Fabric pages.`,sources:[y,g,Le]}],dontConfuse:[{pairId:`fabric-trial-vs-pbi-trial`,a:`Fabric trial capacity`,b:`Power BI individual trial`,difference:[{text:`The Fabric trial is a capacity (F4 or F64) that workspaces run on. The Power BI individual trial is a per-user license. Starting a Fabric trial also gives you a Power BI individual trial if you don’t already have a paid Power BI license.`,sources:[y]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Fabric trial capacity`,definition:`A free F4 or F64 capacity that lasts 60 days, for exploring Fabric workloads. Workspaces use it when their workspace type is set to Trial.`,sources:[y]},{term:`Capacity administrator`,definition:`The person who manages a capacity, including who may assign workspaces to it. Whoever starts a Fabric trial becomes its capacity administrator.`,sources:[y]},{term:`My workspace`,definition:`Each user’s personal workspace. By default it sits on the tenant’s shared capacity but can be assigned to another capacity.`,sources:[v]}],needsVerification:[]}],x=`https://learn.microsoft.com/en-us/`,ze=`${x}fabric/fundamentals/fabric-terminology`,Be=`${x}credentials/certifications/resources/study-guides/dp-600`,Ve=`${x}kusto/query/between-operator?view=microsoft-fabric`,He=`${x}kusto/query/datatypes-string-operators?view=microsoft-fabric`,Ue=`${x}fabric/data-factory/connector-overview`,We=`${x}fabric/data-factory/data-source-management`,S=`${x}fabric/data-factory/data-factory-overview`,Ge=`${x}fabric/data-factory/how-to-access-on-premises-data`,C=`${x}fabric/data-factory/decision-guide-data-movement`,Ke=`${x}fabric/data-engineering/load-data-lakehouse`,qe=`${x}fabric/data-engineering/lakehouse-notebook-load-data`,Je=`${x}fabric/onelake/onelake-shortcuts`,Ye=`${x}fabric/mirroring/overview`,w=`${x}fabric/data-warehouse/ingest-data`,Xe=`${x}fabric/data-warehouse/ingest-data-copy`,Ze=`${x}fabric/data-factory/dataflows-gen2-overview`,T=`${x}fabric/governance/onelake-catalog-overview`,Qe=`${x}fabric/governance/onelake-catalog-explore`,$e=`${x}fabric/real-time-hub/real-time-hub-overview`,et=`${x}fabric/fundamentals/microsoft-fabric-overview`,tt=`${x}fabric/onelake/onelake-overview`,nt=`${x}fabric/fundamentals/decision-guide-lakehouse-warehouse`,E=`${x}fabric/fundamentals/decision-guide-data-store`,D=`${x}fabric/real-time-intelligence/event-house-onelake-availability`,O=`${x}fabric/enterprise/powerbi/onelake-integration-overview`,rt=`${x}fabric/data-warehouse/dimensional-modeling-overview`,k=`${x}fabric/data-warehouse/dimensional-modeling-dimension-tables`,it=`${x}fabric/data-warehouse/dimensional-modeling-fact-tables`,A=`${x}fabric/data-warehouse/dimensional-modeling-load-tables`,j=`${x}fabric/data-warehouse/tsql-surface-area`,at=`${x}fabric/data-warehouse/data-types`,ot=`${x}fabric/data-engineering/lakehouse-sql-analytics-endpoint`,M=`${x}fabric/data-warehouse/data-warehousing`,N=`${x}fabric/data-warehouse/visual-query-editor`,P=`${x}fabric/data-warehouse/query-warehouse`,F=`${x}fabric/data-engineering/tutorial-lakehouse-data-preparation`,st=`${x}fabric/data-science/data-wrangler`,ct=`${x}training/modules/fabric-transform-data-notebooks/3-shape-clean-data`,lt=`${x}power-query/connectors/lakehouse`,ut=`${x}sql/t-sql/statements/create-function-sql-data-warehouse?view=fabric`,dt=`${x}fabric/data-warehouse/how-to-inline-udf`,ft=`${x}fabric/data-engineering/lakehouse-overview`,I=`${x}sql/t-sql/queries/select-qualify-clause-transact-sql?view=fabric`,pt=`${x}sql/t-sql/functions/try-cast-transact-sql?view=fabric`,mt=`${x}sql/t-sql/language-elements/coalesce-transact-sql?view=fabric`,ht=`${x}sql/t-sql/statements/create-view-transact-sql?view=fabric`,gt=`${x}sql/t-sql/statements/create-procedure-transact-sql?view=fabric`,_t=`${x}sql/t-sql/statements/merge-transact-sql?view=fabric`,L=`${x}kusto/query/tutorials/learn-common-operators?view=microsoft-fabric`,R=`${x}kusto/query/summarize-operator?view=microsoft-fabric`,vt=`${x}fabric/real-time-intelligence/kusto-query-set`,yt=`${x}kusto/query/join-operator?view=microsoft-fabric`,bt=`${x}kusto/query/tutorials/join-data-from-multiple-tables?view=microsoft-fabric`,xt=`${x}kusto/query/take-operator?view=microsoft-fabric`,St=`${x}kusto/query/top-operator?view=microsoft-fabric`,Ct=`${x}kusto/query/sort-operator?view=microsoft-fabric`,wt=`${x}kusto/query/where-operator?view=microsoft-fabric`,Tt=`${x}kusto/query/project-operator?view=microsoft-fabric`,Et=`${x}kusto/query/extend-operator?view=microsoft-fabric`,Dt=`${x}kusto/query/bin-function?view=microsoft-fabric`,Ot=`${x}kusto/query/sql-cheat-sheet?view=microsoft-fabric`,z=`${x}dax/dax-queries`,kt=`${x}power-bi/transform-model/dax-query-view`,At=[{machineId:`thread-intake`,pl300Adds:[{text:`In PL-300 you connected Power BI Desktop to a source and loaded it into a model. In DP-600 the destination is a Fabric store (lakehouse, warehouse, eventhouse), and you choose the tool that moves the data: Dataflow Gen2, a pipeline Copy activity, a Copy job, a notebook, mirroring, a shortcut, or T-SQL COPY INTO.`,sources:[S,Ke,w]},{text:`New for DP-600: "access" without copying. Shortcuts and mirroring make data available in OneLake without you building an ETL process, and the exam asks when to use each instead of copying.`,sources:[tt,C]}],overview:[{text:`Every analytics solution starts by connecting to source data and getting it into OneLake, or pointing OneLake at it. Fabric gives you several ways to do this, from no-code to full code. The exam tests whether you pick the right one for the source, the volume, the latency, and the team’s skills.`,sources:[Ke,C]},{text:`Data Factory in Fabric provides the connectors (Learn cites more than 170 sources, including on-premises sources through a gateway) and the movement tools: Copy job, the Copy activity in pipelines, and mirroring. It also provides transformation tools: Dataflow Gen2 and pipeline activities such as notebooks and stored procedures.`,sources:[S]}],bullets:[{bulletId:`P1.1`,tools:[`dataflow-gen2`,`pipeline`,`admin-portal`],concepts:[{text:`A connector is the built-in adapter for a data store. Fabric lists which connectors work as a source or destination in Dataflow Gen2, pipelines (Copy activity), and Copy job.`,sources:[Ue]},{text:`A connection is the saved, reusable definition of how to reach one data source: server, database, authentication method, and an optional privacy level. Connections are managed centrally under Settings > Manage connections and gateways.`,sources:[We]},{text:`For data behind a firewall or on-premises, you install an on-premises data gateway, and Fabric reaches the source through it.`,sources:[Ge]}],howTo:[{text:`Create a cloud connection: Settings > Manage connections and gateways > New > Cloud, then pick the connection type, fill in the source details, and choose an authentication method (for example Basic, OAuth2, or Service Principal).`,sources:[We]},{text:`Learn notes that these cloud connections currently work with pipelines and Kusto. For semantic models and dataflows, you create connections through Power Query Online’s Get data experience.`,sources:[We]},{text:`Removing a connection breaks every item that depends on it, so check dependents first.`,sources:[We]}]},{bulletId:`P1.3`,tools:[`lakehouse`,`warehouse`,`pipeline`,`dataflow-gen2`,`notebook`,`onelake`],concepts:[{text:`Ingest means copying data into Fabric. Access means referencing data where it already lives (shortcuts) or having Fabric keep a managed replica for you (mirroring).`,sources:[tt,Ke]},{text:`Ways into a lakehouse, from simplest to most flexible: upload files, shortcuts, Dataflow Gen2, pipelines (Copy activity), notebook code, and Eventstream for real-time events.`,sources:[Ke]},{text:`Ways into a warehouse: the T-SQL COPY statement (highest throughput, from Azure storage or OneLake), pipelines, dataflows, and T-SQL INSERT...SELECT, SELECT INTO, or CREATE TABLE AS SELECT from other items in the same workspace.`,sources:[w]},{text:`A shortcut is a pointer, like a symbolic link. Deleting the shortcut doesn’t touch the target, but moving or deleting the target breaks the shortcut. Shortcuts can be created in lakehouses and KQL databases.`,sources:[Je]},{text:`Mirroring continuously replicates an operational database into OneLake as Delta tables and creates a SQL analytics endpoint over them. Learn’s data movement guide calls the mirrored destination read-only.`,sources:[Ye,C]}],howTo:[{text:`Learn’s data movement guide recommends: mirroring when you mainly need curated data replicated for reporting; Copy job for raw (bronze) ingestion with incremental loads; Eventstreams for real-time data; and pipelines when you need complex orchestration.`,sources:[C]},{text:`In a notebook, read the source into a DataFrame and write it to the lakehouse. Writing in Delta format with saveAsTable creates a table in the Tables section; writing CSV or Parquet to a Files path stores plain files.`,sources:[qe]},{text:`In a lakehouse, shortcuts in the Tables folder can only be created at the top level, and a Delta target is recognized as a table automatically. Shortcuts in the Files folder can go anywhere and point at any format.`,sources:[Je]},{text:`In a warehouse, create the destination table first, then run COPY INTO with the source path and FILE_TYPE.`,sources:[Xe]}]}],examples:[{title:`Load a Parquet file into a lakehouse table from a notebook`,language:`pyspark`,illustrative:!0,steps:[{code:`df = spark.read.parquet("Files/raw/sales.parquet")`,explain:`Read the source file from the default lakehouse’s Files area into a Spark DataFrame, using a relative path.`},{code:`df.write.mode("overwrite").format("delta").saveAsTable("sales")`,explain:`Write the DataFrame as a Delta table named sales in the Tables section, replacing any existing data.`},{code:`df.write.mode("append").format("delta").saveAsTable("sales")`,explain:`For later loads, append mode adds new rows to the existing Delta table instead of replacing it.`}],sources:[qe]},{title:`Bulk-load a warehouse table with COPY INTO`,language:`tsql`,illustrative:!0,steps:[{code:`CREATE TABLE dbo.Trips (TripId int NULL, FareAmount float NULL, PickupTime datetime2(6) NULL);`,explain:`COPY needs an existing destination table, so create it first with warehouse-supported data types.`},{code:`COPY INTO dbo.Trips
FROM 'https://<storage-account>.blob.core.windows.net/<container>/trips/'
WITH (FILE_TYPE = 'PARQUET');`,explain:`Load all Parquet files from the storage location into the table. FILE_TYPE tells COPY how to parse the files.`},{code:`SELECT COUNT_BIG(*) FROM dbo.Trips;`,explain:`Count the rows to confirm the load worked.`}],sources:[Xe,w]}],traps:[{text:`External Delta tables written with Spark outside the lakehouse’s Tables area aren’t visible to the SQL analytics endpoint. Use a shortcut in the Tables section to expose them.`,sources:[Ke]},{text:`Shortcut names that contain spaces aren’t recognized as Delta tables in the lakehouse.`,sources:[Je]},{text:`COPY INTO is the recommended T-SQL ingestion statement. BULK INSERT exists for compatibility with existing SQL Server code and maps to COPY behavior.`,sources:[Xe,w]},{text:`T-SQL cross-item ingestion (INSERT...SELECT, CTAS) reads tables only from the same workspace. OPENROWSET reads files in Azure storage.`,sources:[w]},{text:`A privacy level set on a connection doesn’t affect DirectQuery connections.`,sources:[We]}],dontConfuse:[{pairId:`shortcut-mirror-copy`,a:`Shortcut vs mirroring`,b:`Copy (Copy job, Copy activity, COPY INTO)`,difference:[{text:`Shortcut: no copy. A live reference to data in another location (OneLake, ADLS, S3, and more). Changes at the source show up immediately.`,sources:[tt,Je]},{text:`Mirroring: Fabric manages continuous replication of a database into OneLake as read-only Delta tables. There is no pipeline to build.`,sources:[Ye,C]},{text:`Copy: you control a physical copy. Copy job (bulk, incremental, CDC), Copy activity (fully customizable, orchestrated in a pipeline), and COPY INTO (T-SQL into a warehouse).`,sources:[C,Xe]}]},{pairId:`dataflow-pipeline-notebook`,a:`Dataflow Gen2 vs pipeline`,b:`Notebook`,difference:[{text:`Dataflow Gen2 is low-code Power Query with 300+ transformations, suited to small and medium data with visual transforms. A pipeline orchestrates activities (copy, notebook, stored procedure, scripts) with schedules, triggers, and control flow. A notebook is code (Spark) and the most flexible option for complex logic.`,sources:[Ze,S,Ke]}]}],renamed:[{oldName:`Power BI dataflow`,newName:`Dataflow Gen1`,examLikely:`The study guide only says "dataflows". Expect Dataflow Gen2 in Fabric scenarios.`,note:`Learn calls the original Power BI dataflow "Gen1" and recommends Dataflow Gen2 for new work. You can’t upgrade Gen1 to Gen2.`,sources:[Ze,ze,Be]}],preview:[{feature:`BCP API for warehouse ingestion`,note:`Client-side bulk ingestion (bcp.exe, SqlBulkCopy) into a warehouse without staging files.`,sources:[w]}],upcoming:[],glossary:[{term:`Connector`,definition:`A built-in adapter that lets Dataflow Gen2, pipelines, and Copy job read from or write to a specific data store.`,sources:[Ue]},{term:`Connection`,definition:`A saved definition of how to reach one data source (location plus authentication), managed in Manage connections and gateways and reused by items.`,sources:[We]},{term:`On-premises data gateway`,definition:`Software you install near an on-premises source so Fabric can reach that data securely from the cloud.`,sources:[Ge]},{term:`Shortcut`,definition:`An object in OneLake that points to data in another location (inside or outside OneLake) without copying it. It appears as a folder and behaves like a symbolic link.`,sources:[Je,ze]},{term:`Mirroring`,definition:`Bringing external data into OneLake without building pipelines. Database mirroring continuously replicates a database into Delta tables with a SQL analytics endpoint; metadata mirroring syncs only catalog metadata and uses shortcuts, so the data stays at its source.`,sources:[Ye,ze]},{term:`Copy job`,definition:`A Data Factory item for data movement without building a pipeline. It supports bulk copy, incremental copy, and change data capture replication.`,sources:[S,C]},{term:`Copy activity`,definition:`A pipeline activity that copies data between supported sources and destinations, with extensive customization.`,sources:[S,C]},{term:`Pipeline`,definition:`A Data Factory item that orchestrates data movement and transformation activities, with schedules, triggers, and control flow. Not the same as a deployment pipeline.`,sources:[ze,S]},{term:`Dataflow Gen2`,definition:`A low-code Power Query-based item for ingesting and transforming data and loading it to destinations such as a lakehouse or warehouse.`,sources:[Ze,ze]},{term:`Notebook`,definition:`An interactive code item (Spark: Python, Scala, Spark SQL, R) used to read, transform, and write lakehouse data.`,sources:[ft]},{term:`COPY INTO`,definition:`The T-SQL statement for high-throughput ingestion of CSV, JSONL, or Parquet files from Azure storage or OneLake into a warehouse table.`,sources:[Xe,w]},{term:`Eventstream`,definition:`A no-code item that captures, transforms, and routes real-time events to destinations such as an eventhouse or lakehouse.`,sources:[ze,C]},{term:`ABFS path`,definition:`The absolute Azure Blob File System path to a file or folder in OneLake. You use it to read data from a lakehouse other than the notebook’s default one.`,sources:[qe]}],needsVerification:[]},{machineId:`bale-catalog`,overview:[{text:`Before you build anything, find out what data already exists. Fabric has two discovery hubs: the OneLake catalog for data items (lakehouses, warehouses, semantic models, and more) and the Real-Time hub for streaming data and events.`,sources:[T,$e]},{text:`Discovering existing items avoids building duplicate pipelines and copies. It also shows ownership, endorsement, sensitivity, and lineage before you depend on an item.`,sources:[Qe,tt]}],bullets:[{bulletId:`P1.2`,tools:[`onelake`,`eventhouse`,`other`],concepts:[{text:`The OneLake catalog has three tabs. Explore finds and inspects items. Govern shows governance insights and recommended actions for data you own. Secure shows workspace roles and OneLake security roles in one place.`,sources:[T]},{text:`Explore lists every item you have access to (or can request access to). You can filter by domain, workspace, item type, endorsement, and more, and each item shows metadata such as owner, description, schema, lineage, and usage.`,sources:[Qe,tt]},{text:`The Real-Time hub is the single, tenant-wide place for streaming data. It lists data streams and KQL tables you can access, and offers connectors for sources such as Azure Event Hubs, IoT Hub, Kafka, database CDC feeds, and Fabric and Azure events.`,sources:[$e,et]}],howTo:[{text:`Open the OneLake catalog from the Fabric navigation pane. It opens on Explore by default. Narrow the list with filters, select an item to see its details without losing the list, and use the item’s options menu to act on it.`,sources:[Qe,T]},{text:`The catalog is also embedded in Teams, Excel, and Copilot Studio, and there is a Catalog Search REST API for programmatic discovery.`,sources:[T]},{text:`In the Real-Time hub, connect a source to create a stream. Process it in the parent eventstream (filter, aggregate, group by, union), analyze it by routing it to a KQL database table, or act on it by setting alerts.`,sources:[$e]}]}],examples:[],traps:[{text:`The OneLake catalog shows items you can access or request access to. It doesn’t grant access by itself.`,sources:[Qe]},{text:`Administrative tasks such as capacity and workspace management are moving from the Admin portal into the catalog’s Govern tab, so a question may describe admin settings "in the OneLake catalog".`,sources:[T]},{text:`Every tenant gets a Real-Time hub automatically. There is nothing to provision.`,sources:[$e]},{text:`You may still meet the older name "OneLake data hub" on some current Learn pages, such as the Power Query Lakehouse connector page, which says to select the lakehouse "in the OneLake data hub". The catalog’s own pages say "OneLake catalog".`,sources:[lt,T]}],dontConfuse:[{pairId:`catalog-vs-rthub`,a:`OneLake catalog`,b:`Real-Time hub`,difference:[{text:`The OneLake catalog is for discovering and governing Fabric items: data at rest, such as lakehouses, warehouses, and semantic models. The Real-Time hub is for discovering and ingesting data in motion: streams, KQL tables, and Fabric or Azure events.`,sources:[T,$e]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`OneLake catalog`,definition:`The central Fabric experience for discovering, governing, and securing items, with Explore, Govern, and Secure tabs.`,sources:[T]},{term:`Real-Time hub`,definition:`A tenant-wide, automatically provisioned place to discover, ingest, process, and act on streaming data and events.`,sources:[$e]}],needsVerification:[]},{machineId:`vat-selector`,overview:[{text:`Choosing the right data store is a design decision the exam tests through scenarios. Learn frames it as a few questions: How does the team develop (Spark or T-SQL)? Do you need multi-table transactions? Is the data structured only, or also semi-structured and unstructured? Is it streaming events?`,sources:[nt,E]}],bullets:[{bulletId:`P1.4`,tools:[`lakehouse`,`warehouse`,`eventhouse`,`sql-analytics-endpoint`],concepts:[{text:`Lakehouse: Spark-first, structured and unstructured data, no multi-table transactions, with a read-only SQL analytics endpoint for T-SQL readers.`,sources:[nt]},{text:`Warehouse: T-SQL-first, structured data, full multi-table ACID transactions, with views, functions, and stored procedures.`,sources:[nt]},{text:`Eventhouse: streaming event data and high-granularity interactive analytics with KQL.`,sources:[E]},{text:`Fabric has other stores too: SQL database in Fabric for operational (OLTP) workloads, and Cosmos DB in Fabric for NoSQL.`,sources:[E]}],howTo:[{text:`Apply the decision points. Spark developers → lakehouse; T-SQL developers → warehouse. Multi-table transactions needed → warehouse. Unstructured or mixed data → lakehouse. Streaming events → eventhouse.`,sources:[nt,E]},{text:`You can mix stores in one workspace, for example landing and transforming in a lakehouse with Spark and then serving curated tables from a warehouse. A warehouse can query lakehouse tables with three-part names.`,sources:[ft,E]}]}],examples:[],traps:[{text:`A team that mostly reads with T-SQL doesn’t automatically need a warehouse. Learn’s scenario picks a lakehouse when the developers use PySpark and the T-SQL users only consume data through the SQL analytics endpoint.`,sources:[E]},{text:`Both lakehouse and warehouse store Delta tables in OneLake and share the same SQL engine. The choice is about how you write and what transactions you need, not where the data lives.`,sources:[nt]}],dontConfuse:[{pairId:`warehouse-vs-sql-database`,a:`Warehouse`,b:`SQL database in Fabric`,difference:[{text:`A warehouse is for analytics: enterprise data warehousing, SQL-based BI, OLAP. SQL database in Fabric is for operational, transactional (OLTP), normalized workloads, and it also exposes a SQL analytics endpoint for analytics.`,sources:[E]}]}],renamed:[],preview:[{feature:`AI functions in Fabric Data Warehouse`,note:`Listed in the data store decision guide as "AI functions (preview)".`,sources:[E,j]}],upcoming:[],glossary:[{term:`SQL database in Fabric`,definition:`A transactional (OLTP) database in Fabric that uses the same SQL Database Engine as Azure SQL Database.`,sources:[E]},{term:`Multi-table transaction`,definition:`A transaction that changes several tables atomically. The warehouse supports them; the lakehouse doesn’t.`,sources:[nt]}],needsVerification:[]},{machineId:`shared-spool`,overview:[{text:`OneLake integration makes data that lives in an engine-specific format also available as Delta tables in OneLake, so other engines can use one copy. The outline names two cases: eventhouse (KQL database) data and semantic model (import) data.`,sources:[D,O]}],bullets:[{bulletId:`P1.5`,tools:[`eventhouse`,`semantic-model`,`onelake`,`lakehouse`],concepts:[{text:`Eventhouse OneLake availability creates a logical copy of KQL database data in Delta format. Other engines (Power BI Direct Lake, warehouse, lakehouse, notebooks) can then query it. There is no extra storage cost.`,sources:[D]},{text:`You can turn it on at the database level (all new tables, optionally back-filling existing ones) or per table. The KQL database’s retention policy also applies to the OneLake copy.`,sources:[D]},{text:`Semantic model OneLake integration writes the data of import-mode tables to Delta tables in OneLake. It needs a Premium P or Fabric F capacity; Pro, PPU, and Embedded A/EM aren’t supported.`,sources:[O]}],howTo:[{text:`Eventhouse: select the database or table, then in the OneLake section of the details pane set Availability to Enabled. Then create a OneLake shortcut from a lakehouse or warehouse, or query it with Direct Lake.`,sources:[D]},{text:`Semantic model: in the model’s settings, turn on OneLake integration. Then run at least one manual or scheduled refresh, because data is only written to Delta during a refresh.`,sources:[O]},{text:`To use the exported tables, create a shortcut in Lakehouse explorer (Tables > New shortcut > Microsoft OneLake) and select the semantic model and its tables.`,sources:[O]}]}],examples:[{title:`Trigger a semantic model export to OneLake with TMSL`,language:`tmsl`,illustrative:!0,steps:[{code:`{
  "export": {
    "layout": "delta",
    "type": "full",
    "objects": [ { "database": "<semantic model name>" } ]
  }
}`,explain:`Run this TMSL command (for example in SSMS over the XMLA endpoint) to export all import tables of the named semantic model as Delta tables. XMLA read-write must be enabled.`}],sources:[O]}],traps:[{text:`While eventhouse OneLake availability is on, you can’t rename tables, alter a column type, apply row-level security to tables, or delete, truncate, or purge data. Turn it off, make the change, and turn it back on.`,sources:[D]},{text:`Turning eventhouse OneLake availability off soft-deletes the data from OneLake.`,sources:[D]},{text:`Eventhouse writes to OneLake in batches and can delay writes (by default up to 3 hours) until it has enough data for well-sized Parquet files. Freshly ingested rows may not appear in OneLake immediately.`,sources:[D]},{text:`Semantic model OneLake integration only applies to import tables, and nothing is exported until a refresh runs.`,sources:[O]}],dontConfuse:[{pairId:`onelake-availability-vs-integration`,a:`Eventhouse OneLake availability`,b:`Semantic model OneLake integration`,difference:[{text:`Eventhouse OneLake availability exposes KQL database data as Delta. You turn it on per database or table, and it follows the KQL retention policy. Semantic model OneLake integration exports import-mode model tables to Delta. You turn it on in model settings, and data appears after a refresh.`,sources:[D,O]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`OneLake availability`,definition:`An eventhouse setting that makes KQL database or table data available in OneLake in Delta format for other Fabric engines.`,sources:[D]},{term:`OneLake integration for semantic models`,definition:`A semantic model setting that writes import-mode table data to Delta tables in OneLake during refresh.`,sources:[O]}],needsVerification:[]},{machineId:`carding-machine`,pl300Adds:[{text:`In PL-300 you removed duplicates, replaced nulls, set types, and filtered rows in Power Query. DP-600 expects the same cleaning in Fabric tools: T-SQL in a warehouse (for example ROW_NUMBER with QUALIFY to remove duplicates, TRY_CAST and COALESCE for types and nulls), Data Wrangler in a notebook, or Dataflow Gen2.`,sources:[I,pt,mt,st,Ze]},{text:`Fabric-specific: warehouse tables support only a subset of T-SQL data types, so type conversion includes mapping unsupported types (such as datetime, money, nvarchar) to supported ones.`,sources:[at]}],overview:[{text:`Raw data has duplicates, gaps, wrong types, and rows you don’t want. Cleaning it before modeling keeps facts correct and keys joinable. In a medallion design, this is the silver layer’s job: fix errors, standardize formats, remove duplicates.`,sources:[A,`${x}fabric/onelake/onelake-medallion-lakehouse-architecture`]}],bullets:[{bulletId:`P2.7`,tools:[`warehouse`,`notebook`,`dataflow-gen2`],concepts:[{text:`Duplicates: identify them by the business key and keep one row per key, for example the latest. In T-SQL, ROW_NUMBER() OVER (PARTITION BY key ORDER BY ...) numbers the rows within each key, and QUALIFY keeps row 1 without a subquery.`,sources:[I]},{text:`Missing or null values: replace them with a default (COALESCE returns the first non-null argument), drop the rows, or map them to an "Unknown" dimension member so fact rows still have a valid key.`,sources:[mt,A,k]},{text:`In a notebook, Data Wrangler offers point-and-click operations that generate pandas or PySpark code: Drop duplicate rows, Drop missing values, Fill missing values, Change column type, and Filter.`,sources:[st]},{text:`In PySpark, dropDuplicates() removes exact duplicate rows, and dropDuplicates(["order_id"]) keeps one row per business key. fillna() replaces nulls with defaults (for example a dictionary of column → value), and dropna(subset=[...]) drops rows where a required column is null.`,sources:[ct]}],howTo:[{text:`Warehouse: clean in staging tables, then load the dimensional tables with set-based INSERT...SELECT or CTAS. Learn recommends staging source data in a separate schema that business users never see.`,sources:[A]},{text:`Notebook: open Data Wrangler on a DataFrame, apply cleaning operations, preview each one, then export the generated code back to the notebook as a function.`,sources:[st]},{text:`Dataflow Gen2: use Power Query transformations (300+ available) and write the result to a lakehouse or warehouse destination.`,sources:[Ze]}]},{bulletId:`P2.8`,tools:[`warehouse`,`notebook`,`dataflow-gen2`],concepts:[{text:`Warehouse tables support: bit, smallint, int, bigint, decimal/numeric, float, real, date, time, datetime2, char, varchar, varbinary, and uniqueidentifier.`,sources:[at]},{text:`Unsupported in warehouse tables, with Learn’s alternatives: money → decimal; datetime/smalldatetime → datetime2; nchar/nvarchar → char/varchar; text/ntext → varchar; image → varbinary; tinyint → smallint; json → varchar.`,sources:[at]},{text:`TRY_CAST converts a value to a target type and returns NULL instead of an error when the conversion fails. That makes bad values easy to find and handle.`,sources:[pt]}],howTo:[{text:`Convert to the dimensional model’s types during the ETL transform step, before loading.`,sources:[A]},{text:`Use TRY_CAST in a SELECT to convert, then filter or COALESCE the NULLs it returns for values that didn’t convert.`,sources:[pt,mt]}]},{bulletId:`P2.9`,tools:[`warehouse`,`sql-analytics-endpoint`,`notebook`,`dataflow-gen2`],concepts:[{text:`WHERE filters rows before grouping and window functions. HAVING filters groups after aggregation. QUALIFY filters after window functions are calculated.`,sources:[I]},{text:`Filtering early, when staging, keeps only relevant rows in later steps.`,sources:[A,ct]}],howTo:[{text:`T-SQL: add a WHERE clause to the SELECT that feeds your load. Notebook: use Data Wrangler’s Filter operation or a DataFrame filter. Dataflow Gen2: filter rows in Power Query before the destination step.`,sources:[I,st,Ze]}]}],examples:[{title:`Keep the latest row per customer, fix types, and fill nulls (warehouse)`,language:`tsql`,illustrative:!0,steps:[{code:`SELECT CustomerID,
       COALESCE(Region, 'Unknown') AS Region,
       TRY_CAST(SignupDate AS date) AS SignupDate,
       ModifiedAt
FROM staging.Customer`,explain:`Read from the staging table, replace a missing Region with "Unknown", and convert SignupDate to date (NULL if a value isn’t a valid date).`},{code:`WHERE CustomerID IS NOT NULL`,explain:`Filter out rows with no business key before any window function runs.`},{code:`QUALIFY ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY ModifiedAt DESC) = 1;`,explain:`Number each customer’s rows from newest to oldest and keep only the newest, which removes duplicates without a subquery.`}],sources:[I,mt,pt,A]},{title:`Remove duplicates and handle nulls in a notebook (PySpark)`,language:`pyspark`,illustrative:!0,steps:[{code:`df = spark.table("raw_sales")`,explain:`Load the lakehouse table into a Spark DataFrame.`},{code:`deduped_df = df.dropDuplicates(["order_id"])`,explain:`Keep one row per order_id. With no column list, dropDuplicates() removes only rows that are identical in every column.`},{code:`clean_df = deduped_df.fillna({"region": "Unknown", "discount": 0})`,explain:`Replace nulls column by column: a missing region becomes "Unknown" and a missing discount becomes 0, so calculations don’t return null.`},{code:`clean_df = clean_df.dropna(subset=["customer_id"])`,explain:`Drop rows that have no customer_id, because they can’t be joined to customer data.`}],sources:[ct]}],traps:[{text:`Don’t use nvarchar or datetime when creating warehouse tables; they aren’t supported for persisted storage. Use varchar and datetime2.`,sources:[at]},{text:`datetime2 and time are limited to 6 digits of fractional-second precision in the warehouse.`,sources:[at]},{text:`uniqueidentifier columns can be stored in a warehouse, but the SQL analytics endpoint reads them as binary. Joins between a warehouse and a lakehouse endpoint on such a column don’t work as expected.`,sources:[at]},{text:`Filters in WHERE run before window functions, so a WHERE can’t reference ROW_NUMBER(). Use QUALIFY, a CTE, or a subquery.`,sources:[I]}],dontConfuse:[{pairId:`where-having-qualify`,a:`WHERE vs HAVING`,b:`QUALIFY`,difference:[{text:`WHERE filters individual rows before grouping and window functions. HAVING filters grouped results after GROUP BY. QUALIFY filters after window functions are evaluated. Order: FROM → WHERE → GROUP BY → HAVING → window functions → QUALIFY → ORDER BY.`,sources:[I]}]}],renamed:[],preview:[{feature:`ALTER TABLE … ALTER COLUMN in Warehouse`,note:`Changing an existing column’s type in place is in preview. Otherwise ALTER TABLE supports ADD nullable column, DROP COLUMN, and PRIMARY KEY, UNIQUE, or FOREIGN KEY constraints only with NOT ENFORCED.`,sources:[j]}],upcoming:[],glossary:[{term:`QUALIFY`,definition:`A T-SQL clause (Fabric Warehouse and SQL analytics endpoint) that filters rows on the result of window functions such as ROW_NUMBER, without a subquery.`,sources:[I]},{term:`TRY_CAST`,definition:`A T-SQL function that converts a value to a type and returns NULL if the conversion fails.`,sources:[pt]},{term:`COALESCE`,definition:`A T-SQL expression that returns the first of its arguments that isn’t NULL.`,sources:[mt]},{term:`Data Wrangler`,definition:`A notebook tool for exploring and cleaning pandas or Spark DataFrames through a UI that generates reusable code.`,sources:[st]},{term:`Staging table`,definition:`A table that holds extracted source data for the ETL process. It is emptied at the start of each run and never exposed to business users.`,sources:[A]}],needsVerification:[]},{machineId:`twisting-frame`,pl300Adds:[{text:`In PL-300 you used Merge queries and Group By in Power Query. In DP-600 the same operations appear as T-SQL JOIN and GROUP BY in a warehouse (often inside CREATE TABLE AS SELECT), as PySpark join() and groupBy() or Spark SQL in a notebook, and as Merge queries in Dataflow Gen2 or the visual query editor.`,sources:[w,F,N]}],overview:[{text:`Combining (merging on keys or appending rows) and aggregating (summarizing to a coarser grain) are core ETL transforms. They build dimension tables from several sources and produce summary tables for reporting.`,sources:[A]}],bullets:[{bulletId:`P2.5`,tools:[`warehouse`,`notebook`,`dataflow-gen2`,`lakehouse`],concepts:[{text:`Aggregation can reduce a fact table’s dimensionality or raise its grain. For example, if you don’t need sales order numbers, group by all the dimension keys and sum the measures.`,sources:[A]},{text:`Learn’s lakehouse tutorial builds business aggregate tables (for example sales by date and city) from the star schema in a notebook, using PySpark or Spark SQL.`,sources:[F]}],howTo:[{text:`PySpark: join the DataFrames, groupBy the grouping columns, apply sum(), rename the result columns, and write the result as a Delta table.`,sources:[F]},{text:`T-SQL in a warehouse: use CREATE TABLE AS SELECT ... GROUP BY to materialize the aggregate as a new table.`,sources:[w,A]}]},{bulletId:`P2.6`,tools:[`warehouse`,`sql-analytics-endpoint`,`notebook`,`dataflow-gen2`],concepts:[{text:`Merging (joining) combines data from different sources on matching keys, for example product data from two systems that share a SKU. Appending (a union) stacks rows that share the same structure.`,sources:[A]},{text:`Warehouse T-SQL can join tables across warehouses and lakehouses in the same workspace by using three-part names (item.schema.table).`,sources:[w,P]}],howTo:[{text:`Visual query editor: drag two tables onto the canvas, choose Merge queries as new, and pick the key columns and the join kind (for example Inner).`,sources:[N]},{text:`T-SQL: CREATE TABLE AS SELECT with JOINs across items is a set-based load, which Learn calls likely the most efficient way to load dimensional tables.`,sources:[A,w]}]}],examples:[{title:`Join and aggregate sales by date and city (notebook)`,language:`pyspark`,illustrative:!0,steps:[{code:`sale = spark.read.format("delta").load("Tables/dbo/fact_sale")
date = spark.read.format("delta").load("Tables/dbo/dimension_date")
city = spark.read.format("delta").load("Tables/dbo/dimension_city")`,explain:`Load the fact table and two dimension tables from the lakehouse into DataFrames.`},{code:`joined = (sale.join(date, sale.InvoiceDateKey == date.Date, "inner")
              .join(city, sale.CityKey == city.CityKey, "inner"))`,explain:`Inner-join the fact rows to their date and city rows on the key columns.`},{code:`agg = (joined.groupBy("Date", "City")
          .sum("TotalExcludingTax", "Profit")
          .withColumnRenamed("sum(Profit)", "SumOfProfit"))`,explain:`Group by date and city, sum the measures, and give the summed column a readable name.`},{code:`agg.write.mode("overwrite").format("delta").save("Tables/dbo/aggregate_sale_by_date_city")`,explain:`Save the aggregate as a new Delta table that reports can read.`}],sources:[F]},{title:`Join across items and aggregate into a new table (warehouse)`,language:`tsql`,illustrative:!0,steps:[{code:`CREATE TABLE Reporting.dbo.SalesByRegion
AS`,explain:`CTAS creates the target table from the result of the SELECT that follows.`},{code:`SELECT p.Category, s.Region, SUM(s.Amount) AS TotalAmount
FROM SalesLakehouse.dbo.Sales AS s
JOIN Reporting.dbo.Products AS p ON s.ProductID = p.ProductID`,explain:`Join a lakehouse table and a warehouse table in the same workspace using three-part names.`},{code:`GROUP BY p.Category, s.Region;`,explain:`Aggregate to one row per category and region.`}],sources:[w,P]}],traps:[{text:`Cross-database queries with three-part names work only within the same workspace.`,sources:[P,w]},{text:`Aggregating a fact table loses detail for good. Learn notes that dropping columns like sales order numbers by grouping raises the grain, so do it only when no analysis needs that detail.`,sources:[A]}],dontConfuse:[{pairId:`merge-vs-append`,a:`Merge (join)`,b:`Append (union)`,difference:[{text:`Merge adds columns by matching rows on keys. Append adds rows from sources with the same structure. Example: product attributes from two systems (merge on SKU) vs sales from several systems (append into one set).`,sources:[A]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`CREATE TABLE AS SELECT (CTAS)`,definition:`T-SQL that creates a new table and fills it from a SELECT in one set-based statement. Commonly used to load warehouse tables.`,sources:[w,A]},{term:`Three-part name`,definition:`An item.schema.object reference (for example Sales.dbo.Orders) used to query another warehouse or lakehouse endpoint in the same workspace.`,sources:[P,w]},{term:`Grain`,definition:`The level of detail one fact row represents. Aggregation raises (coarsens) the grain.`,sources:[A,it]}],needsVerification:[]},{machineId:`dye-vat`,pl300Adds:[{text:`In PL-300 you added custom and conditional columns in Power Query, or calculated columns in the model. In DP-600 enrichment happens upstream: withColumn() in PySpark, computed expressions in T-SQL CTAS or views, or Dataflow Gen2 columns, so the stored table already has the columns.`,sources:[F,A,w]}],overview:[{text:`Enriching data means adding what the source doesn’t have: derived columns (full name, gross revenue, year and quarter), lookups from other tables, or whole new tables such as a date dimension. Doing it in the data store means every consumer gets the same values.`,sources:[A,k]}],bullets:[{bulletId:`P2.2`,tools:[`notebook`,`warehouse`,`dataflow-gen2`,`lakehouse`],concepts:[{text:`Calculated columns in the ETL: concatenate first and last name into a full name, or multiply unit price by quantity to get gross revenue.`,sources:[A]},{text:`New tables: a date dimension should cover the date range of all fact tables (and future dates for budgets or forecasts). Learn recommends extending it with a T-SQL stored procedure.`,sources:[k,A]},{text:`Dataflow Gen2 can add columns while ingesting, for example by changing data types, adding or removing columns, or using functions to produce calculated columns.`,sources:[w]}],howTo:[{text:`Notebook: use withColumn() to add derived columns (Learn’s tutorial adds Year, Quarter, and Month from a date), then write the Delta table, optionally partitioned by the new columns.`,sources:[F]},{text:`Warehouse: compute the columns in the SELECT of a CTAS or INSERT...SELECT, or expose them in a view.`,sources:[w,M]}]}],examples:[{title:`Add date-part columns and partition the table (notebook)`,language:`pyspark`,illustrative:!0,steps:[{code:`from pyspark.sql.functions import col, year, quarter, month
df = spark.read.format("parquet").load("Files/raw/fact_sale")`,explain:`Import the date functions and read the raw sales files.`},{code:`df = (df.withColumn("Year", year(col("InvoiceDateKey")))
        .withColumn("Quarter", quarter(col("InvoiceDateKey")))
        .withColumn("Month", month(col("InvoiceDateKey"))))`,explain:`Add three new columns derived from the invoice date.`},{code:`df.write.mode("overwrite").format("delta").partitionBy("Year", "Quarter").save("Tables/dbo/fact_sale")`,explain:`Save as a Delta table partitioned by the new Year and Quarter columns.`}],sources:[F]},{title:`The same enrichment in Spark SQL`,language:`sparksql`,illustrative:!0,steps:[{code:`CREATE OR REPLACE TABLE delta.\`Tables/dbo/fact_sale\`
USING DELTA
PARTITIONED BY (Year, Quarter)
AS`,explain:`Create or replace a partitioned Delta table from a query.`},{code:"SELECT *, year(InvoiceDateKey) AS Year, quarter(InvoiceDateKey) AS Quarter, month(InvoiceDateKey) AS Month\nFROM parquet.`Files/raw/fact_sale`;",explain:`Select every source column plus the three derived date columns.`}],sources:[F]}],traps:[{text:`Columns derived in the ETL are stored once and shared by every engine that reads the table.`,sources:[A,tt]},{text:`If a dimensional model is built only in Power Query inside a semantic model, it can’t manage historical change. Learn says to use a warehouse with periodic ETL when history matters.`,sources:[rt]}],dontConfuse:[],renamed:[],preview:[],upcoming:[],glossary:[{term:`Date dimension`,definition:`A dimension with one row per date covering every date the facts use (plus future dates for plans), with attributes like year, quarter, and month.`,sources:[k]},{term:`Partitioning (Delta)`,definition:`Writing a Delta table split into folders by column values (for example Year and Quarter), as Learn’s lakehouse tutorial does with partitionBy.`,sources:[F]}],needsVerification:[]},{machineId:`weave-planner`,pl300Adds:[{text:`PL-300 taught star schemas inside a semantic model. DP-600 asks you to build the star in the data store itself: surrogate keys, slowly changing dimensions, unknown members, and ETL into warehouse or lakehouse tables. Learn calls a dimensional model in the warehouse a recommended prerequisite for enterprise semantic models.`,sources:[rt,k,A]}],overview:[{text:`A star schema has fact tables (measurements of events) surrounded by dimension tables (the things you filter and group by). It is optimized for analytic queries, with fewer joins and simpler maintenance, and it is the recommended design for a Fabric warehouse.`,sources:[rt]}],bullets:[{bulletId:`P2.3`,tools:[`warehouse`,`lakehouse`,`notebook`,`pipeline`],concepts:[{text:`Dimension tables describe entities (product, customer, date). Each should have a surrogate key: a single-column, meaningless integer key generated in the warehouse. The source system’s natural (business) key is kept as a column for matching during ETL.`,sources:[k]},{text:`Slowly changing dimensions: Type 1 overwrites the member; Type 2 inserts a new versioned row with validity dates, which needs the surrogate key; Type 3 tracks limited history in extra columns and is rarely used.`,sources:[k]},{text:`Fact tables store dimension keys plus measures at a declared grain. Learn names three types: transaction (one row per event), periodic snapshot (measured at intervals, semi-additive measures), and accumulating snapshot (milestones of a process, several date keys).`,sources:[it]},{text:`Add special dimension members (for example Unknown or N/A) so a fact row whose dimension lookup fails still gets a valid key.`,sources:[k,A]}],howTo:[{text:`Warehouse ETL: stage the source data, then process dimensions (match on business keys and apply SCD type 1 updates or type 2 expire-and-insert), then load facts by looking up the current surrogate key for each dimension. Use pipelines to orchestrate stored procedures and SQL scripts.`,sources:[A]},{text:`Lakehouse: Learn’s tutorial writes fact_sale and the dimension_* tables as Delta tables from notebooks, forming a star schema in the lakehouse.`,sources:[F]},{text:`Load fact tables incrementally where possible; truncating and reloading a large fact table is a last resort.`,sources:[A]},{text:`Never truncate and fully reload a dimension with generated surrogate keys. It breaks fact references and SCD type 2 history. Record source deletions as soft deletes (an IsDeleted bit column) instead.`,sources:[A]}]},{bulletId:`P2.4`,tools:[`warehouse`,`sql-analytics-endpoint`,`notebook`],concepts:[{text:`Dimension tables should almost always be denormalized: hierarchy levels (for example subcategory and category) are flattened into one product table, accepting some repeated values.`,sources:[k]},{text:`A snowflake dimension is the normalized exception, spread over several related tables. In a semantic model a hierarchy can only use columns from one table, so Learn suggests exposing a snowflake through a view that joins it back into one denormalized result.`,sources:[k]}],howTo:[{text:`Denormalize with joins in the ETL (CTAS or INSERT...SELECT) or in a view over the normalized tables.`,sources:[k,A]},{text:`Many small lookup dimensions can be combined into one junk dimension.`,sources:[k]}]}],examples:[{title:`Flatten a snowflaked product dimension with a view (warehouse)`,language:`tsql`,illustrative:!0,steps:[{code:`CREATE VIEW dbo.vDimProduct
AS`,explain:`A view stores the denormalizing query so consumers see one product table.`},{code:`SELECT p.Product_SK, p.ProductCode, p.ProductName,
       s.SubcategoryName, c.CategoryName`,explain:`Return the surrogate key, the natural key, and the attributes from all three hierarchy levels.`},{code:`FROM dbo.Product AS p
JOIN dbo.Subcategory AS s ON p.Subcategory_FK = s.Subcategory_SK
JOIN dbo.Category AS c ON s.Category_FK = c.Category_SK;`,explain:`Join product to subcategory to category, flattening the snowflake into a single denormalized row per product.`}],sources:[k,ht]},{title:`Apply type 1 changes to a dimension with MERGE (warehouse)`,language:`tsql`,illustrative:!0,steps:[{code:`MERGE dbo.DimCustomer AS tgt
USING staging.Customer AS src
ON tgt.CustomerID = src.CustomerID`,explain:`Match staged source rows to existing dimension rows on the natural (business) key.`},{code:`WHEN MATCHED THEN UPDATE SET tgt.Region = src.Region`,explain:`Type 1: overwrite the changed attribute on the existing member.`},{code:`WHEN NOT MATCHED BY TARGET THEN
  INSERT (CustomerID, Region) VALUES (src.CustomerID, src.Region);`,explain:`Insert customers the dimension doesn’t have yet.`}],sources:[_t,j,A]}],traps:[{text:`Surrogate keys should be the smallest suitable integer type with no business meaning, except date and time keys, which Learn suggests storing as YYYYMMDD and HHMM.`,sources:[A,k]},{text:`IDENTITY columns exist in Fabric Data Warehouse but with limitations. Check them before relying on IDENTITY for surrogate keys.`,sources:[A,j]},{text:`Primary key, unique, and foreign key constraints can be added in a warehouse only with NOT ENFORCED.`,sources:[j]},{text:`SCD type 3 is hard to use in a semantic model. Learn suggests considering type 2 instead.`,sources:[k]},{text:`MERGE is generally available in Fabric Data Warehouse.`,sources:[j]}],dontConfuse:[{pairId:`scd1-vs-scd2`,a:`SCD type 1`,b:`SCD type 2`,difference:[{text:`Type 1 overwrites the attribute, so history is lost and reports show the current value everywhere. Type 2 expires the current row and inserts a new version, so facts keep pointing at the version that was true when they happened.`,sources:[k,A]}]},{pairId:`star-vs-snowflake`,a:`Star (denormalized dimension)`,b:`Snowflake dimension`,difference:[{text:`A star keeps each dimension in one denormalized table, which means fewer joins and simpler models. A snowflake normalizes a dimension into related tables, which is less redundant but needs a joining view before a semantic model can build hierarchies on it.`,sources:[k,rt]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Star schema`,definition:`A dimensional design with a fact table at the center and denormalized dimension tables around it, optimized for analytic queries.`,sources:[rt]},{term:`Fact table`,definition:`A table of measurements for events or observations at a declared grain, holding dimension keys and (usually additive) measures.`,sources:[rt,it]},{term:`Dimension table`,definition:`A table describing an entity used to filter and group facts, such as product, customer, or date.`,sources:[rt]},{term:`Surrogate key`,definition:`A single-column, warehouse-generated key with no business meaning, used to relate dimensions to facts and to track SCD type 2 history.`,sources:[k]},{term:`Natural key`,definition:`The key from the source system (also called a business key), used by ETL to match incoming rows to dimension members.`,sources:[k]},{term:`Slowly changing dimension (SCD)`,definition:`A technique for handling changes to dimension attributes over time: type 1 overwrite, type 2 versioned rows, type 3 limited history.`,sources:[k]},{term:`Snowflake dimension`,definition:`A dimension normalized into several related tables, for example Product → Subcategory → Category.`,sources:[k]},{term:`Denormalization`,definition:`Storing precomputed, redundant data (such as flattened hierarchy levels) in one table to simplify and speed up queries.`,sources:[k]},{term:`Junk dimension`,definition:`A dimension that combines many small, low-cardinality lookup attributes into one table.`,sources:[k]},{term:`Soft delete`,definition:`Marking a dimension member as no longer valid (for example IsDeleted = 1) instead of physically deleting it.`,sources:[A]},{term:`MERGE`,definition:`A T-SQL statement that inserts, updates, or deletes target rows based on a join with a source. Generally available in Fabric Data Warehouse.`,sources:[_t,j]}],needsVerification:[]},{machineId:`inspection-bench`,overview:[{text:`Analytics engineers constantly query data to check loads, explore sources, and answer questions. In a warehouse or SQL analytics endpoint you have two editors in the Fabric portal: the no-code visual query editor and the SQL query editor. You can also use external tools like SSMS or VS Code through the SQL connection string.`,sources:[P,N]}],bullets:[{bulletId:`P3.1`,tools:[`warehouse`,`sql-analytics-endpoint`],concepts:[{text:`The visual query editor uses the Power Query diagram view. You drag tables onto a canvas and apply steps such as merge, filter, and group without writing SQL. It works on warehouses, SQL analytics endpoints, and mirrored databases.`,sources:[N]},{text:`View SQL shows the T-SQL generated from your steps. You can then open it in the SQL editor to edit it.`,sources:[N]}],howTo:[{text:`Select New visual query, drag tables from the Explorer, use Merge queries as new to join on a key, apply filter or group steps, then save the result as a view (Save as view) or as a table (Save as table, which uses CREATE TABLE AS SELECT).`,sources:[N]},{text:`For a cross-warehouse visual query, add the other warehouse with + Warehouses and merge tables from both.`,sources:[N,P]}]},{bulletId:`P3.2`,tools:[`warehouse`,`sql-analytics-endpoint`],concepts:[{text:`SELECT, WHERE, GROUP BY, HAVING, and ORDER BY work as in SQL Server. Fabric also supports newer syntax: FROM-first queries, GROUP BY ALL and ORDER BY ALL, QUALIFY, and analytic functions such as MEDIAN and APPROX_QUANTILE.`,sources:[j]},{text:`Cross-database queries join tables from other warehouses or lakehouse endpoints in the same workspace by using three-part names.`,sources:[P]}],howTo:[{text:`Select New SQL query, write the query, and run it. To query another item, add it to the Explorer, then reference it as item.schema.table.`,sources:[P]}]}],examples:[{title:`Filter, aggregate, and filter groups (SQL analytics endpoint or warehouse)`,language:`tsql`,illustrative:!0,steps:[{code:`SELECT c.Region, COUNT(*) AS Orders, SUM(o.Amount) AS Revenue`,explain:`Return one row per region with an order count and total revenue.`},{code:`FROM SalesLakehouse.dbo.Orders AS o
JOIN dbo.Customer AS c ON o.CustomerID = c.CustomerID`,explain:`Join a lakehouse table (three-part name) to a local table.`},{code:`WHERE o.OrderDate >= '2026-01-01'`,explain:`Keep only orders from 2026 before grouping.`},{code:`GROUP BY c.Region
HAVING SUM(o.Amount) > 10000
ORDER BY Revenue DESC;`,explain:`Group by region, keep only regions above 10,000, and sort by revenue descending.`}],sources:[P,I]}],traps:[{text:`The visual query editor only runs read-only SELECT queries: no DDL or DML. It supports only Power Query operations that can fold to SQL.`,sources:[N]},{text:`Visualize results doesn’t support queries with ORDER BY.`,sources:[N]},{text:`Some visual steps can’t be translated to SQL, and the editor then won’t let you save the query as a view.`,sources:[N]}],dontConfuse:[{pairId:`visual-vs-sql-editor`,a:`Visual query editor`,b:`SQL query editor`,difference:[{text:`The visual editor is no-code (Power Query diagram), read-only, and limited to foldable steps, but it can show the generated SQL and save results as a view or table. The SQL editor runs any supported T-SQL you write, including DDL and DML on a warehouse.`,sources:[N,P]}]}],renamed:[],preview:[{feature:`Nested common table expressions`,note:`Standard and sequential CTEs are generally available; nested CTEs are in preview in Fabric Warehouse and the SQL analytics endpoint.`,sources:[j]}],upcoming:[],glossary:[{term:`Visual query editor`,definition:`A no-code query builder in the Fabric portal, based on Power Query diagram view, for warehouses, SQL analytics endpoints, and mirrored databases.`,sources:[N]},{term:`Cross-database query`,definition:`A T-SQL query that joins objects from several warehouses or SQL analytics endpoints in the same workspace by using three-part names.`,sources:[P]}],needsVerification:[]},{machineId:`recipe-book`,overview:[{text:`Views, functions, and stored procedures package SQL logic so it can be reused, secured, and called by pipelines. They hold business rules (a clean customer list, an ETL step) in the database instead of in every report or notebook.`,sources:[M,j]}],bullets:[{bulletId:`P2.1`,tools:[`warehouse`,`sql-analytics-endpoint`,`pipeline`],concepts:[{text:`Fabric Data Warehouse supports T-SQL views, stored procedures, and functions. You can also create views, functions, and procedures on the SQL analytics endpoint of a lakehouse, over its Delta tables.`,sources:[j,M]},{text:`On the SQL analytics endpoint, Learn specifically lists views, inline table-valued functions, and procedures as objects you can create to encapsulate business logic.`,sources:[M]},{text:`Pipelines can run stored procedures and SQL scripts, which is how Learn suggests orchestrating ETL steps. A typical one is a procedure that extends the date dimension.`,sources:[A,S]}],howTo:[{text:`Write CREATE VIEW, CREATE PROCEDURE, or CREATE FUNCTION in the SQL query editor of the warehouse or SQL analytics endpoint. The visual query editor can also save a query as a view.`,sources:[ht,gt,N]},{text:`Use a view to hide joins (for example flattening a snowflake dimension) and to apply object-level permissions to a defined slice of data.`,sources:[k,ot]}]}],examples:[{title:`A view, an inline table-valued function, and a procedure`,language:`tsql`,illustrative:!0,steps:[{code:`CREATE VIEW dbo.vActiveCustomer AS
SELECT CustomerID, CustomerName, Region
FROM dbo.DimCustomer
WHERE IsCurrent = 1 AND IsDeleted = 0;`,explain:`A view that returns only current, non-deleted customer versions, so reports never see expired SCD rows or soft deletes.`},{code:`CREATE FUNCTION dbo.fnSalesByRegion (@Region varchar(50))
RETURNS TABLE
AS RETURN
  SELECT OrderID, Amount FROM dbo.FactSales WHERE Region = @Region;`,explain:`An inline table-valued function: a parameterized query that returns a table and can be used in FROM like a view.`},{code:`CREATE PROCEDURE dbo.LoadDailySales
AS
BEGIN
  INSERT INTO dbo.FactSales (OrderID, Region, Amount)
  SELECT OrderID, Region, Amount FROM staging.Sales;
END;`,explain:`A stored procedure for one ETL step, which a pipeline can call on a schedule. Because it inserts data, it must live in a warehouse, not on a SQL analytics endpoint.`},{code:`EXEC dbo.LoadDailySales;`,explain:`Run the procedure, from the SQL editor or from a pipeline’s stored procedure activity.`}],sources:[ht,gt,M,j,A]}],traps:[{text:`You can create a procedure on a SQL analytics endpoint, but it can’t modify data there. The endpoint is read-only for INSERT, UPDATE, and DELETE.`,sources:[ot,j]},{text:`SQL security set on the SQL analytics endpoint (including permissions on views) applies only when data is read through the endpoint, not through Spark or other paths.`,sources:[ot]},{text:`Scalar UDFs are a preview feature in Fabric Data Warehouse. To be used in a SELECT … FROM query on user tables, a scalar UDF must be inlineable; you can still create one that isn’t, but it works only in a limited number of scenarios.`,sources:[ut,dt]}],dontConfuse:[{pairId:`endpoint-vs-warehouse`,a:`SQL analytics endpoint`,b:`Warehouse`,difference:[{text:`Read-only vs read-write: on the SQL analytics endpoint, T-SQL can define and query objects but can’t insert, update, or delete data, and tables can’t be created there. To change lakehouse data, use Spark. The warehouse supports full DDL and DML with multi-table transactions.`,sources:[ot,M,j]},{text:`Where logic lives: both support views, functions, and stored procedures. On the endpoint they sit over the lakehouse’s Delta tables; in the warehouse they can also load and change data.`,sources:[j,M]},{text:`What’s visible: the endpoint shows only Delta tables in the lakehouse’s Tables area (including shortcuts). Files-area data isn’t exposed.`,sources:[ot,ft]}]}],renamed:[],preview:[{feature:`Scalar user-defined functions in Fabric Data Warehouse`,note:`Scalar UDFs (and external UDFs that call a Fabric User Data Function) are preview features. Check whether a function is inlineable with is_inlineable in sys.sql_modules.`,sources:[ut,dt]}],upcoming:[],glossary:[{term:`View`,definition:`A saved SELECT query that behaves like a table, used to hide joins, apply logic, and scope permissions.`,sources:[ht]},{term:`Stored procedure`,definition:`Saved T-SQL statements run by name (EXEC), often called from pipelines for ETL steps.`,sources:[gt,A]},{term:`Scalar user-defined function (UDF)`,definition:`A T-SQL function that returns a single value. In Fabric Data Warehouse it is a preview feature, and Fabric inlines it into the calling query when the function and query meet the inlining requirements.`,sources:[ut,dt]},{term:`Inline table-valued function (TVF)`,definition:`A function that returns a table from a single SELECT and can take parameters. Supported on the SQL analytics endpoint and the warehouse.`,sources:[M]}],contested:[{topic:`Materialized views in Fabric Data Warehouse`,readings:[{text:`What is Fabric Data Warehouse? describes the warehouse’s T-SQL surface area as having "full multi-table ACID transaction support, materialized views, functions, and stored procedures".`,sources:[M]},{text:`The T-SQL surface area page lists "Materialized views" under commands that "aren’t supported", and warns not to use them even if they appear to succeed.`,sources:[j]}],guidance:`Learn doesn’t settle this, so no question or puzzle in the game depends on it.`},{topic:`Release status of inline table-valued functions in Fabric Data Warehouse`,readings:[{text:`The Fabric CREATE FUNCTION page’s opening note lists only scalar UDFs and external UDFs as preview features in Fabric Data Warehouse.`,sources:[ut]},{text:`The same page’s argument description says "In inline TVFs (preview), you define the TABLE return value through a single SELECT statement."`,sources:[ut]}],guidance:`Both readings agree that inline TVFs can be created in a warehouse and on the SQL analytics endpoint; questions use them only for what they do, never for their release status.`}],needsVerification:[]},{machineId:`tension-meter`,overview:[{text:`KQL (Kusto Query Language) is the query language of eventhouses and KQL databases. It reads top to bottom: start from a table and pipe it through operators that filter, shape, and aggregate. It is built for fast exploration of large, time-based event data.`,sources:[L,vt]}],bullets:[{bulletId:`P3.3`,tools:[`eventhouse`],concepts:[{text:`Core operators: where (filter rows), project (choose or compute columns), extend (add computed columns, keeping all others), summarize (aggregate by groups), sort/order by, top (first N by a column), take (sample rows), distinct, and count.`,sources:[L,R]},{text:`summarize groups rows by the by expressions and computes aggregations (count(), sum(), dcount(), min(), max(), and others) for each group. Use bin() to group numeric or datetime values into ranges, for example bin(Timestamp, 1h).`,sources:[R]},{text:`Operator order matters: each operator transforms the output of the previous one, so top before where gives different results from where before top.`,sources:[L]}],howTo:[{text:`Write KQL in a KQL queryset (or the database’s query environment) attached to a KQL database. A queryset can also query Azure Data Explorer and Azure Monitor sources, and it supports many SQL functions.`,sources:[vt]}]}],examples:[{title:`Filter, shape, and aggregate events`,language:`kql`,illustrative:!0,steps:[{code:`StormEvents`,explain:`Start from the table. Every following line pipes this result to the next operator.`},{code:`| where State == 'TEXAS' and EventType == 'Flood'`,explain:`Keep only Texas flood events (KQL string comparison with ==).`},{code:`| extend Duration = EndTime - StartTime`,explain:`Add a calculated Duration column while keeping all existing columns.`},{code:`| summarize Events = count(), MaxDamage = max(DamageProperty) by bin(StartTime, 30d)`,explain:`Group the events into 30-day buckets and count them, also returning the largest property damage per bucket.`},{code:`| sort by StartTime asc`,explain:`Sort ascending. Without asc, KQL sort defaults to descending.`}],sources:[L,R]},{title:`Filter rows and choose columns (where, project)`,language:`kql`,illustrative:!0,steps:[{code:`StormEvents
| where StartTime between (datetime(2007-08-01) .. datetime(2007-08-30 23:59:59))`,explain:`where keeps only rows whose StartTime falls in August 1–30, 2007; between takes an inclusive range.`},{code:`| where State == 'TEXAS' and EventType == 'Flood'`,explain:`A second where narrows further. == is case-sensitive equality, and conditions combine with and.`},{code:`| project StartTime, EndTime, State, EventType, DamageProperty`,explain:`project returns only these five columns, in this order, like a SQL SELECT list.`}],sources:[wt,Tt,L,Ve,He]},{title:`Add a calculated column and keep everything else (extend)`,language:`kql`,illustrative:!0,steps:[{code:`StormEvents
| where State == 'TEXAS' and EventType == 'Flood'`,explain:`Start from Texas flood events.`},{code:`| extend Duration = EndTime - StartTime`,explain:`extend appends a Duration column (a timespan) and keeps all existing columns.`},{code:`| project StartTime, Duration, DamageProperty`,explain:`project trims the output to the columns you want to read, including the new one.`}],sources:[Et,L]},{title:`Count events per hour (summarize … by bin())`,language:`kql`,illustrative:!0,steps:[{code:`StormEvents`,explain:`Start from the event table.`},{code:`| summarize EventCount = count() by bin(StartTime, 1h)`,explain:`bin() rounds each StartTime down to the hour, so summarize returns one row per hour with the number of events in it.`},{code:`| sort by StartTime asc`,explain:`Sort the hourly buckets oldest first; without asc the sort would be descending.`}],sources:[R,Dt,Ct]},{title:`Rank rows (sort by vs top)`,language:`kql`,illustrative:!0,steps:[{code:`StormEvents
| sort by State asc, StartTime desc`,explain:`sort by (same as order by) orders by several columns: state A–Z, newest storm first within each state.`},{code:`StormEvents
| top 3 by InjuriesDirect`,explain:`top returns the first 3 rows by InjuriesDirect, descending by default. It is equivalent to sort by InjuriesDirect | take 3.`}],sources:[Ct,St]},{title:`Preview a table quickly (take)`,language:`kql`,illustrative:!0,steps:[{code:`StormEvents
| take 5`,explain:`take returns up to 5 rows, with no guarantee which ones. Use it to look at the shape of the data, not to rank (take and limit are equivalent).`}],sources:[xt]},{title:`Combine two tables (join)`,language:`kql`,illustrative:!0,steps:[{code:`StormEvents
| summarize PropertyDamage = sum(DamageProperty) by State`,explain:`Total property damage per state from the events table.`},{code:`| join kind=inner PopulationData on State`,explain:`Join each state’s total to PopulationData on the State column. kind=inner keeps only matching states; without kind the default flavor is innerunique.`},{code:`| project State, PropertyDamagePerCapita = PropertyDamage / Population
| sort by PropertyDamagePerCapita`,explain:`Compute damage per person and sort descending by it (sort is descending by default).`}],sources:[yt,bt]}],traps:[{text:`A KQL join without kind= uses innerunique, which de-duplicates the left side’s keys first. It is not the same as an inner join. Specify kind=inner when you want every matching row.`,sources:[yt]},{text:`For best join performance, put the smaller table on the left side of a KQL join.`,sources:[yt]},{text:`sort in KQL is descending by default. Add asc for ascending.`,sources:[L]},{text:`Automatic hourly bins for datetime columns in summarize are no longer supported. Use an explicit bin(), such as bin(Timestamp, 1h).`,sources:[R]},{text:`Most summarize aggregations ignore null values (avg sums and counts only non-null values), but the standard count() counts every row, nulls included.`,sources:[R]},{text:`take returns arbitrary rows for a quick preview. Use top N by a column when you need a defined ranking.`,sources:[L]}],dontConfuse:[{pairId:`sql-vs-kql`,a:`SQL (WHERE, GROUP BY, SELECT, ORDER BY)`,b:`KQL (where, summarize … by, project, sort by)`,difference:[{text:`SQL WHERE ↔ KQL | where (equality is == in KQL, not =). SQL SELECT col list ↔ | project col list. SQL GROUP BY with aggregates ↔ | summarize agg() by cols (the grouping and the aggregation are one operator). SQL ORDER BY ↔ | sort by (or order by), and SELECT TOP n … ORDER BY ↔ | top n by. KQL reads top to bottom as a pipeline, starting from the table name rather than SELECT.`,sources:[Ot]},{text:`In a KQL queryset you can prefix a SQL query with a comment line containing explain to see its KQL translation.`,sources:[Ot]}]},{pairId:`project-vs-extend`,a:`project`,b:`extend`,difference:[{text:`project returns only the columns you list (and can compute new ones). extend keeps every existing column and appends the new calculated columns at the end.`,sources:[L]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Kusto Query Language (KQL)`,definition:`The pipe-based query language for eventhouses, KQL databases, Azure Data Explorer, and Azure Monitor.`,sources:[L]},{term:`KQL queryset`,definition:`A Fabric item for writing, saving, and running KQL queries against KQL databases and other Kusto-based sources.`,sources:[vt,ze]},{term:`summarize`,definition:`The KQL operator that groups rows by key expressions and computes aggregations per group.`,sources:[R]},{term:`take`,definition:`A KQL operator that returns up to N arbitrary rows (same as limit). Good for previews, not for ranking.`,sources:[xt]},{term:`top (KQL)`,definition:`A KQL operator returning the first N rows by an expression, descending by default; equivalent to sort by … | take N.`,sources:[St]},{term:`join (KQL)`,definition:`A KQL operator that merges rows of two tables on matching columns. Flavors include innerunique (default), inner, leftouter, rightouter, fullouter, and anti or semi joins.`,sources:[yt]},{term:`bin()`,definition:`A KQL function that rounds values down into fixed-size buckets (for example 1h or 30d), used to group time series in summarize.`,sources:[R]}],needsVerification:[]},{machineId:`dax-scale`,pl300Adds:[{text:`PL-300 used DAX to write measures and calculated columns. DP-600 adds writing whole DAX queries (EVALUATE) to select, filter, and aggregate data from a semantic model, and running them in DAX query view (Desktop or the web), notebooks (semantic link), or tools like SSMS and DAX Studio.`,sources:[z,kt]}],overview:[{text:`Every Power BI visual sends a DAX query to the semantic model. Writing DAX queries yourself lets you inspect data, test measures before adding them to the model, and debug slow visuals. Performance Analyzer can show the query a visual generated.`,sources:[z]}],bullets:[{bulletId:`P3.4`,tools:[`semantic-model`,`power-bi-desktop`,`notebook`],concepts:[{text:`A DAX query needs one keyword: EVALUATE followed by a table expression. That can be a table name, a table function (SUMMARIZECOLUMNS, FILTER, TOPN, SELECTCOLUMNS, and others), or a scalar wrapped in braces, such as EVALUATE {[Total Sales]}.`,sources:[z]},{text:`Optional keywords: DEFINE (query-scoped MEASURE and VAR definitions), ORDER BY, and START AT. There can be many EVALUATE statements but only one DEFINE block, and it must come first.`,sources:[z]},{text:`Select = choose the columns (SUMMARIZECOLUMNS group-by columns or SELECTCOLUMNS). Filter = add filter arguments or wrap the table in FILTER. Aggregate = name/expression pairs such as "Orders", [Orders].`,sources:[z]}],howTo:[{text:`In Power BI Desktop, open DAX query view from the left rail. In the service or Fabric portal, choose Write DAX queries from the semantic model’s context menu or details page.`,sources:[kt]},{text:`Measures defined with DEFINE MEASURE exist only for the query. Use the CodeLens "Update model" actions or the Update model with changes button to save them into the model.`,sources:[kt,z]}]}],examples:[{title:`Select, filter, and aggregate with SUMMARIZECOLUMNS`,language:`dax`,illustrative:!0,steps:[{code:`DEFINE
  MEASURE Sales[Avg Profit per Order] = DIVIDE([Total Sales Profit], [Orders])`,explain:`Define a query-scoped measure. It overrides any model measure with the same name for this query only.`},{code:`EVALUATE
SUMMARIZECOLUMNS(
  'Date'[Month Name], 'Date'[Month of Year],`,explain:`Start the query. These are the group-by columns. Include Month of Year so you can sort by it later.`},{code:`  FILTER(VALUES('Product'[Category]), [Category] = "Clothing"),`,explain:`Filter argument: only rows for the Clothing category.`},{code:`  "Orders", [Orders],
  "Avg Profit per Order", [Avg Profit per Order]
)`,explain:`Aggregations: name/expression pairs evaluated for each group.`},{code:`ORDER BY 'Date'[Month of Year] ASC`,explain:`Sort the result. DAX queries ignore the model’s Sort by column setting, so the sort column must be in the query.`}],sources:[z]}],traps:[{text:`Sort by column settings in the model don’t apply to DAX query results. Include the sort column in the query and ORDER BY it.`,sources:[z]},{text:`TOPN picks its rows by its own ordering argument, not by ORDER BY. ORDER BY only sorts the rows TOPN already returned.`,sources:[z]},{text:`Query-scoped TABLE and COLUMN definitions are for internal use and can cause runtime errors. Stick to MEASURE and VAR in DEFINE.`,sources:[z]}],dontConfuse:[{pairId:`query-measure-vs-model-measure`,a:`DEFINE MEASURE (query-scoped)`,b:`Model measure`,difference:[{text:`A DEFINE MEASURE lives only while the query runs and doesn’t change the model, even when it overrides a model measure of the same name. A model measure is saved in the semantic model and used by every report. DAX query view can promote query measures into the model.`,sources:[z,kt]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`DAX query`,definition:`A DAX statement that returns a table, built from EVALUATE plus optional DEFINE, ORDER BY, and START AT.`,sources:[z]},{term:`EVALUATE`,definition:`The one required DAX query keyword. It runs a table expression and returns its result.`,sources:[z]},{term:`DAX query view`,definition:`An editor in Power BI Desktop and on the web (Write DAX queries) for writing and running DAX queries against a semantic model.`,sources:[kt]},{term:`Semantic link`,definition:`Fabric notebook functionality that reads semantic model data and can run DAX queries from Python.`,sources:[z]}],needsVerification:[]}],B=`https://learn.microsoft.com/en-us/`,V=`${B}power-bi/connect-data/service-dataset-modes-understand`,jt=`${B}power-bi/transform-model/desktop-storage-mode`,H=`${B}fabric/fundamentals/direct-lake-overview`,U=`${B}fabric/fundamentals/direct-lake-how-it-works`,Mt=`${B}fabric/fundamentals/direct-lake-analyze-query-processing`,Nt=`${B}fabric/fundamentals/direct-lake-security-integration`,W=`${B}power-bi/transform-model/desktop-composite-models`,G=`${B}power-bi/guidance/star-schema`,K=`${B}power-bi/guidance/relationships-many-to-many`,q=`${B}power-bi/transform-model/desktop-relationships-understand`,J=`${B}power-bi/transform-model/calculation-groups`,Y=`${B}power-bi/create-reports/desktop-dynamic-format-strings`,X=`${B}power-bi/create-reports/power-bi-field-parameters`,Z=`${B}fabric/enterprise/powerbi/service-premium-large-models`,Pt=`${B}dax/var-dax`,Ft=`${B}dax/best-practices/dax-variables`,It=`${B}dax/window-function-dax`,Lt=`${B}dax/offset-function-dax`,Rt=`${B}dax/information-functions-dax`,zt=`${B}dax/filter-functions-dax`,Bt=`${B}dax/sumx-function-dax`,Vt=`${B}dax/calculate-function-dax`,Ht=`${B}dax/isinscope-function-dax`,Ut=`${B}dax/hasonevalue-function-dax`,Wt=`${B}dax/selectedvalue-function-dax`,Gt=`${B}power-bi/create-reports/performance-analyzer`,Kt=`${B}power-bi/guidance/power-bi-optimization`,qt=`${B}power-bi/guidance/import-modeling-data-reduction`,Jt=`${B}dax/best-practices/dax-avoid-avoid-filter-as-filter-argument`,Yt=`${B}dax/best-practices/dax-divide-function-operator`,Xt=`${B}dax/best-practices/dax-countrows`,Q=`${B}power-bi/connect-data/incremental-refresh-overview`,$=`${B}power-bi/connect-data/incremental-refresh-configure`,Zt=`${B}fabric/data-warehouse/semantic-models`,Qt=`${B}power-bi/transform-model/dax-query-view`,$t=`${B}fabric/data-warehouse/dimensional-modeling-overview`,en=`${B}fabric/fundamentals/fabric-terminology`,tn=`${B}credentials/certifications/resources/study-guides/dp-600`,nn=[{machineId:`loom-gearbox`,pl300Adds:[{text:`PL-300 compared Import, DirectQuery, and Dual. DP-600 adds Direct Lake: a Fabric-only storage mode that reads Delta tables from OneLake into the VertiPaq engine without copying data. It comes in two flavors, Direct Lake on OneLake and Direct Lake on SQL analytics endpoints.`,sources:[H]},{text:`You also need to know Fabric capacity guardrails (Parquet files, row groups, rows, model size per SKU) and how each mode is licensed. Direct Lake needs a Fabric capacity; Import and DirectQuery work with any license.`,sources:[H]}],overview:[{text:`A semantic model table’s storage mode decides where the data lives at query time and which engine answers. That drives performance, freshness, refresh cost, and which features you can use. Storage mode is set per table; a model that mixes modes is a composite model.`,sources:[H,V]}],bullets:[{bulletId:`S1.1`,tools:[`semantic-model`,`power-bi-desktop`,`lakehouse`,`warehouse`],concepts:[{text:`Import: data is copied, compressed, and held in memory by VertiPaq. Fast queries and full DAX and Power Query, but data is only as fresh as the last refresh, and a full refresh reloads everything.`,sources:[V]},{text:`DirectQuery: the model holds only metadata, and each query is translated to native queries against the source. Freshest data and Import model size limits don’t apply, but slower and limited to M and DAX that can be translated. Calculated tables aren’t supported.`,sources:[V]},{text:`Dual: the table can act as Import or DirectQuery, and the engine picks per query. It is typically used for dimension tables in a composite model so relationships with DirectQuery facts stay regular.`,sources:[V,jt]},{text:`Direct Lake: VertiPaq loads only the columns a query needs, straight from Delta tables in OneLake. Its "refresh" is framing (a metadata update that takes seconds), not a data copy. Learn says it suits large lakehouses and warehouses, and is especially useful when importing the whole volume is impractical.`,sources:[H,U]}],howTo:[{text:`Pick by scenario. Self-service, agile, Power Query prep → Import. Near-real-time or huge external sources → DirectQuery. Large Fabric data already prepared as Delta → Direct Lake. Mix where needed → composite.`,sources:[H,V]},{text:`For most tables you set the storage mode when you add the table. You can change a DirectQuery table to Import or Dual but not back (except in web modeling or live editing, which have version control). Direct Lake on OneLake tables can be converted to Import with semantic link labs in a notebook.`,sources:[jt]},{text:`If you can’t modify the lakehouse (for example, an analyst without write permission), Learn suggests adding Import tables, because Import supports Power Query data preparation inside the model.`,sources:[H]}]}],examples:[],traps:[{text:`Import and Direct Lake are both answered by VertiPaq. DirectQuery is the one that federates queries to the source.`,sources:[H]},{text:`Scheduled refresh limits for Import are 8 per day on shared capacity and 48 per day on Premium.`,sources:[V]},{text:`Direct Lake doesn’t support hybrid tables or model-level partitions. Partition at the Delta table level instead.`,sources:[H]},{text:`Default semantic models are gone: since September 5, 2025 they’re no longer created with a warehouse, lakehouse, or mirrored item, and existing ones were decoupled by November 30, 2025. Questions that assume an automatic model are outdated.`,sources:[Zt]}],dontConfuse:[{pairId:`storage-modes`,a:`Import vs DirectQuery`,b:`Direct Lake vs composite`,difference:[{text:`Import: copy into VertiPaq, refresh to update, any license. DirectQuery: no copy, native queries to the source each time, any license. Direct Lake: no copy, VertiPaq pages columns in from OneLake Delta tables and framing updates metadata, Fabric capacity required. Composite: not a separate engine but a model whose tables use different modes (Import, DirectQuery, Dual, Direct Lake).`,sources:[H,V]},{text:`Refresh: Import refresh copies data, which can take considerable time and use significant source and capacity resources. Direct Lake refresh is framing (seconds, metadata only). DirectQuery needs no data refresh.`,sources:[H,V]}]}],renamed:[{oldName:`Power BI dataset`,newName:`Semantic model`,examLikely:`"Semantic model". The current study guide uses it throughout.`,note:`Microsoft renamed the dataset content type to semantic model in Power BI and Fabric.`,sources:[Zt,tn]}],preview:[],upcoming:[],glossary:[{term:`Semantic model`,definition:`The metadata layer of tables, relationships, measures, and data connections that Power BI reports query. Formerly called a dataset.`,sources:[en,Zt]},{term:`Storage mode`,definition:`A per-table property of a semantic model (Import, DirectQuery, Dual, Direct Lake) that decides how the table’s data is stored and queried.`,sources:[H,jt]},{term:`Import mode`,definition:`A storage mode that copies data into the model’s compressed in-memory VertiPaq store. Refresh is needed to update it.`,sources:[V]},{term:`DirectQuery`,definition:`A storage mode that stores no data and sends native queries to the source each time the model is queried.`,sources:[V]},{term:`Dual storage mode`,definition:`A table that can behave as Import or DirectQuery, with the engine choosing per query. It keeps relationships regular in composite models.`,sources:[V,jt]},{term:`Direct Lake`,definition:`A Fabric storage mode in which VertiPaq loads Delta table columns directly from OneLake on demand, without importing or using DirectQuery.`,sources:[H,en]},{term:`VertiPaq`,definition:`The in-memory engine that answers queries for Import and Direct Lake tables from a cache of the columns.`,sources:[H,U]}],needsVerification:[]},{machineId:`warp-frame`,pl300Adds:[{text:`You know star schemas and one-to-many relationships from PL-300. DP-600 goes further with many-to-many designs: bridging tables for many-to-many dimensions, many-to-many cardinality for higher-grain facts such as targets, and regular vs limited relationships, which matter in composite and Fabric models.`,sources:[K,q]},{text:`The semantic model’s star often sits on a star already built in the warehouse or lakehouse. Learn calls a warehouse dimensional model a recommended prerequisite for enterprise semantic models.`,sources:[$t]}],overview:[{text:`The semantic model’s tables and relationships decide how filters flow and whether measures add up correctly. A clean star (facts in the middle, dimensions around, one-to-many relationships, with bi-directional filtering only as needed) is the default. Many-to-many cases need deliberate patterns.`,sources:[G,K,q]}],bullets:[{bulletId:`S1.2`,tools:[`semantic-model`,`power-bi-desktop`],concepts:[{text:`Classify each model table as a fact table (events, measures to summarize) or a dimension table (attributes to filter and group by), and relate them with one-to-many relationships from dimension to fact.`,sources:[G]},{text:`Role-playing dimensions: one dimension (usually Date) relates to a fact several ways (order date, ship date). Only one relationship between two tables can be active; the others are inactive and used through USERELATIONSHIP in measures.`,sources:[G]},{text:`Prefer explicit measures (DAX) over implicit ones. MDX clients such as Analyze in Excel need explicit measures, and calculation groups require them.`,sources:[G,J]}],howTo:[{text:`In model view, create relationships on matching key columns with the same data type, set cardinality (one-to-many in a star), and keep cross-filter direction single unless a pattern needs Both.`,sources:[q,G]},{text:`Flatten snowflaked dimensions into single tables (or views upstream) so hierarchies can be built from one table.`,sources:[G]}]},{bulletId:`S1.3`,tools:[`semantic-model`,`power-bi-desktop`],concepts:[{text:`Many-to-many dimensions (for example customers and joint bank accounts): don’t relate the dimensions directly. Add a bridging table holding the pairs, relate it with two one-to-many relationships, and set one of them to Both so filters reach the fact table.`,sources:[K]},{text:`Higher-grain facts (for example targets by category and month): relate the date part through the Date table, and for a non-date column such as Category use a many-to-many relationship that filters in a single direction, from dimension to fact.`,sources:[K]},{text:`Regular vs limited relationships: a relationship is regular when the engine can confirm a unique "one" side. It is limited when the cardinality is many-to-many or when it crosses source groups in a composite model.`,sources:[q]}],howTo:[{text:`Bridge pattern: add each entity with its ID column, add the bridging table, create the one-to-many relationships, set one to bi-directional, and hide the bridge unless it has reporting columns.`,sources:[K]},{text:`Avoid relating two fact tables directly with many-to-many. Learn says it limits how visuals can filter and group, and it can hide data quality issues.`,sources:[K]}]}],examples:[],traps:[{text:`Balances or totals reached through a bridge are non-additive. A customer’s balance across joint accounts doesn’t sum to the grand total.`,sources:[K]},{text:`Limited relationships use inner-join semantics and no blank "unknown" row is added, so unmatched rows silently disappear. RELATED can’t be used across a limited relationship.`,sources:[q]},{text:`Both sides of a relationship should have the same data type, and Direct Lake requires matching types. A one-side column with duplicates makes Direct Lake queries fail.`,sources:[q,H]},{text:`A column can’t be related to another column in the same table. Parent-child hierarchies need a different technique.`,sources:[q]}],dontConfuse:[{pairId:`regular-vs-limited`,a:`Regular relationship`,b:`Limited relationship`,difference:[{text:`Regular: a guaranteed unique "one" side, table expansion with LEFT OUTER JOIN semantics, a blank row added for missing keys, and RELATED works. Limited: many-to-many cardinality or a cross source group relationship, INNER JOIN at query time, no blank row, no RELATED, and RLS topology restrictions.`,sources:[q]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Bridging table`,definition:`A table that stores pairs of keys to resolve a many-to-many relationship between two dimensions with two one-to-many relationships.`,sources:[K]},{term:`Regular relationship`,definition:`A relationship where the engine can confirm the "one" side is unique (for example one-to-many inside one source group).`,sources:[q]},{term:`Limited relationship`,definition:`A relationship without a guaranteed unique "one" side (many-to-many, or cross source group). It is resolved with inner-join semantics at query time.`,sources:[q]},{term:`Role-playing dimension`,definition:`One dimension that filters a fact in several roles (for example Date as order, ship, and delivery date), with one active relationship and the rest inactive.`,sources:[G]},{term:`Disconnected table`,definition:`A model table with no relationships, used to accept user input (for example from a slicer) for calculations.`,sources:[q]},{term:`Explicit measure`,definition:`A measure defined with a DAX formula, as opposed to an implicit measure created by summarizing a column in a visual.`,sources:[G]}],needsVerification:[]},{machineId:`punch-card-reader`,pl300Adds:[{text:`PL-300 covered CALCULATE, time intelligence, and basic measures. DP-600 names more families: variables (VAR/RETURN), iterators (the X functions), table filtering, window functions (WINDOW, OFFSET, INDEX with ORDERBY and PARTITIONBY), and information functions (ISINSCOPE, HASONEVALUE, SELECTEDMEASURE, and others).`,sources:[Ft,It,Rt,zt]}],overview:[{text:`Most business logic in a semantic model lives in DAX measures. Writing them well, with readable variables, the right iterator, precise filters, and context-aware logic, is the core skill of the Loom Hall.`,sources:[Ft,Vt]}],bullets:[{bulletId:`S1.4`,tools:[`semantic-model`,`power-bi-desktop`],concepts:[{text:`Variables: VAR names a value or table and RETURN gives the result. A variable is evaluated once, outside the filters the RETURN expression applies, which improves performance, readability, and debugging. It also replaces the old EARLIER pattern.`,sources:[Ft,Pt]},{text:`Iterators: functions like SUMX evaluate an expression for each row of a table and then aggregate. Use SUM when you only need a plain column total.`,sources:[Bt]},{text:`Table filtering: CALCULATE changes filter context with Boolean filter expressions, table expressions (often FILTER), or modifier functions (ALL, REMOVEFILTERS, KEEPFILTERS, ALLSELECTED, and others).`,sources:[Vt,zt]},{text:`Window functions: WINDOW returns rows in an interval around the current row (relative or absolute), OFFSET returns the row a given distance before or after, and INDEX returns a row by position. All of them take ORDERBY and PARTITIONBY. Related functions include RANK, ROWNUMBER, RUNNINGSUM, and MOVINGAVERAGE.`,sources:[It,Lt,zt]},{text:`Information functions inspect context and values: ISINSCOPE (is this hierarchy level being grouped?), HASONEVALUE (is the column filtered to one value?), ISFILTERED, ISBLANK, and SELECTEDMEASURE (used inside calculation groups). SELECTEDVALUE (a filter function) returns the single value or an alternate result.`,sources:[Rt,Ht,Ut,Wt]}],howTo:[{text:`Write measures in Power BI Desktop, in web modeling, or in DAX query view with DEFINE MEASURE, then add them to the model with the Update model options.`,sources:[Qt]}]}],examples:[{title:`Year-over-year growth with a variable`,language:`dax`,illustrative:!0,steps:[{code:`Sales YoY Growth % =
VAR SalesPriorYear =
    CALCULATE([Sales], PARALLELPERIOD('Date'[Date], -12, MONTH))`,explain:`Calculate last year’s sales once and store it in a variable instead of repeating the expression.`},{code:`RETURN
    DIVIDE([Sales] - SalesPriorYear, SalesPriorYear)`,explain:`Use the variable twice in the result. Learn reports this runs in about half the time of the version without a variable, and DIVIDE handles a zero or blank denominator.`}],sources:[Ft,Yt]},{title:`Iterator over a filtered table`,language:`dax`,illustrative:!0,steps:[{code:`Territory 5 Freight =
SUMX(
    FILTER(InternetSales, InternetSales[SalesTerritoryID] = 5),
    InternetSales[Freight]
)`,explain:`FILTER returns only territory 5’s rows; SUMX then sums Freight row by row over that table.`}],sources:[Bt]},{title:`Running total within each fiscal year (window function)`,language:`dax`,illustrative:!0,steps:[{code:`RunningSum =
SUMX(
    WINDOW(
        1, ABS, 0, REL,`,explain:`The window starts at the first row of the partition (1, ABS) and ends at the current row (0, REL).`},{code:`        ALLSELECTED('Date'[Fiscal Year], 'Date'[Month Number Of Year]),
        PARTITIONBY('Date'[Fiscal Year])
    ),
    [Total Sales]
)`,explain:`Rows are the selected year/month combinations, restarted for each fiscal year; SUMX adds Total Sales across the window, which gives a year-to-date running sum.`}],sources:[It]},{title:`Different logic at different hierarchy levels`,language:`dax`,illustrative:!0,steps:[{code:`Sales Note =
IF(
    ISINSCOPE('Product'[Product]),
    "Product level",
    "Subtotal"
)`,explain:`ISINSCOPE returns TRUE only when the visual groups by Product at this level, so you can treat detail rows and subtotals differently.`}],sources:[Ht]}],traps:[{text:`A measure can’t reference variables defined outside its own expression, and you can’t reference a column of a table variable with TableName[Column] syntax.`,sources:[Pt]},{text:`Variables are evaluated once, before the RETURN expression’s filters apply. Putting a VAR before a CALCULATE doesn’t make it respond to that CALCULATE’s filters.`,sources:[Ft]},{text:`SUMX isn’t supported in DirectQuery mode when used in calculated columns or RLS rules.`,sources:[Bt]}],dontConfuse:[{pairId:`hasonevalue-vs-isinscope`,a:`HASONEVALUE / SELECTEDVALUE`,b:`ISINSCOPE`,difference:[{text:`HASONEVALUE is TRUE when filtering leaves exactly one distinct value (for example a slicer selection), and SELECTEDVALUE returns that value. ISINSCOPE is TRUE when the column is the level a visual is currently grouping by in a hierarchy, which is what you test to separate detail rows from subtotals.`,sources:[Ut,Wt,Ht]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`VAR / RETURN`,definition:`DAX syntax that stores the result of an expression in a named variable (VAR) and returns the final expression (RETURN).`,sources:[Pt]},{term:`Iterator`,definition:`A DAX function (such as SUMX) that evaluates an expression for each row of a table and then aggregates the results.`,sources:[Bt]},{term:`Window function`,definition:`A DAX function (WINDOW, OFFSET, INDEX) that returns rows by position within a sorted, partitioned table: relative to the current row (OFFSET), at an absolute position (INDEX), or either (WINDOW).`,sources:[It,Lt]},{term:`Information function`,definition:`A DAX function that tests a value or the evaluation context, such as ISBLANK, ISFILTERED, ISINSCOPE, or HASONEVALUE.`,sources:[Rt]},{term:`Filter context`,definition:`The set of filters in effect when a measure is evaluated. CALCULATE modifies it with Boolean filters, table filters, or modifier functions.`,sources:[Vt]}],needsVerification:[]},{machineId:`jacquard-head`,pl300Adds:[{text:`PL-300 included creating calculation groups. DP-600 adds dynamic format strings (on measures and on calculation items) and field parameters, and expects you to know how they interact: calculation groups switch measures to the variant data type, and they force explicit measures.`,sources:[J,Y,X]}],overview:[{text:`These three features cut down measure sprawl and let report readers choose what they see. Calculation groups apply one piece of logic (for example YTD or YoY%) to any measure. Dynamic format strings change number formats by context without turning numbers into text. Field parameters let readers swap the measures or columns in a visual.`,sources:[J,Y,X]}],bullets:[{bulletId:`S1.5`,tools:[`semantic-model`,`power-bi-desktop`],concepts:[{text:`A calculation group is a special table whose calculation items are DAX expressions using SELECTEDMEASURE() as a placeholder for whatever measure is in the visual. Precedence controls the order when several calculation groups apply.`,sources:[J]},{text:`A dynamic format string is a DAX expression that returns a format string. The measure keeps its numeric type, unlike FORMAT(), which returns text. It can be set on a measure or on a calculation item (for example to show YOY% as a percentage).`,sources:[Y,J]},{text:`A field parameter is a calculated table, defined with a DAX table constructor using NAMEOF(), listing fields (columns and/or measures) with display names and order. Put it on a slicer and in a visual’s field well so readers can switch fields.`,sources:[X,H]}],howTo:[{text:`Calculation group: Model view > Calculation group. Power BI asks to turn on Discourage implicit measures. Then add calculation items, set any dynamic format strings, and set precedence. You can also script one in TMDL view.`,sources:[J]},{text:`Dynamic format string: select the measure, choose Format > Dynamic in Measure tools, then write the DAX that returns the format string.`,sources:[Y]},{text:`Field parameter: Modeling > New parameter > Fields, pick the fields, and use the generated slicer. Use column-based parameters in axis wells and measure-based ones in value wells.`,sources:[X]}]}],examples:[{title:`Use a calculation item inside a measure`,language:`dax`,illustrative:!0,steps:[{code:`Orders YOY% =
CALCULATE(
    [Orders],
    'Time Intelligence'[Time Calculation] = "YOY%"
)`,explain:`Filtering the calculation group column to the YOY% item applies that item’s expression to [Orders], with no separate YoY measure needed.`}],sources:[J]},{title:`Define a field parameter`,language:`dax`,illustrative:!0,steps:[{code:`Parameter = {
    ("Customer", NAMEOF('Customer'[Customer]), 0),
    ("Category", NAMEOF('Product'[Category]), 1),
    ("Color", NAMEOF('Product'[Color]), 2)
}`,explain:`Each row is a display name, a field reference via NAMEOF, and a sort order. Learn says to keep exactly these three columns with unique values.`}],sources:[X]},{title:`Dynamic currency format string`,language:`dax`,illustrative:!0,steps:[{code:`SELECTEDVALUE(
    'Country/Region Currency Format Strings'[Format],
    "\\$#,0.00;(\\$#,0.00);\\$#,0.00"
)`,explain:`Look up the format for the selected country or region; if none is selected, fall back to US dollars. The measure stays numeric.`}],sources:[Y,Wt]}],traps:[{text:`Adding any calculation group changes every measure in reports to the variant data type. Removing all calculation groups reverts them.`,sources:[J]},{text:`Calculation groups need Discourage implicit measures turned on, so dragging a numeric column to sum it no longer works; create explicit measures.`,sources:[J]},{text:`Field parameters can’t use implicit measures, aren’t supported by AI visuals or Q&A, can’t be drillthrough or tooltip link fields, and can’t be created on a live connection without a local model.`,sources:[X]},{text:`Switching a measure from a dynamic format string back to a static one can’t be undone. You must re-enter the DAX expression.`,sources:[Y]},{text:`In Direct Lake on SQL models, calculation groups and field parameters are among the few calculated tables allowed.`,sources:[H]}],dontConfuse:[{pairId:`calcgroup-vs-fieldparam`,a:`Calculation group`,b:`Field parameter`,difference:[{text:`A calculation group changes how measures are calculated (it applies one DAX expression to whatever measure is selected). A field parameter changes which field a visual shows (the reader swaps measures or columns) without changing any calculation.`,sources:[J,X]}]},{pairId:`dfs-vs-format`,a:`Dynamic format string`,b:`FORMAT() function`,difference:[{text:`FORMAT() returns text, which can break charts that need numbers. A dynamic format string only changes the display format, and the measure stays numeric.`,sources:[Y]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Calculation group`,definition:`A model table of calculation items that apply DAX logic to the measure in context through SELECTEDMEASURE(), reducing duplicate measures.`,sources:[J]},{term:`Calculation item`,definition:`One DAX expression inside a calculation group, such as YTD or YOY%, selectable from the group’s column.`,sources:[J]},{term:`SELECTEDMEASURE`,definition:`A DAX function that stands for the measure currently being evaluated, used in calculation items.`,sources:[J,Rt]},{term:`Dynamic format string`,definition:`A DAX expression that returns the format string for a measure or calculation item based on context, keeping the value numeric.`,sources:[Y]},{term:`Field parameter`,definition:`A parameter table that lets report readers choose which measures or columns a visual uses, through a slicer.`,sources:[X]},{term:`Discourage implicit measures`,definition:`A model property that stops report authors from summarizing columns directly. It is required by calculation groups.`,sources:[J]}],needsVerification:[]},{machineId:`wide-beam`,overview:[{text:`Import models have a default size limit of 1 GB in the service. The large semantic model storage format lifts that limit, up to the capacity’s size or a maximum the capacity admin sets. It is required for models beyond 10 GB and recommended whenever you write to models through XMLA.`,sources:[Z]}],bullets:[{bulletId:`S1.6`,tools:[`semantic-model`,`admin-portal`,`workspace`],concepts:[{text:`Use cases: models that grow beyond the default limit as they refresh (often with incremental refresh), and models managed by XMLA-based tools, because the large format can improve XMLA write performance even for small models.`,sources:[Z]},{text:`Availability: Fabric F SKUs, Premium P SKUs, Embedded A SKUs, Premium Per User, and Pro workspaces on Reserved Capacity for Pro Workspaces.`,sources:[Z]},{text:`On-demand load is on by default for large models. Only the data pages a query needs are paged into memory, which speeds up reloading evicted models.`,sources:[Z]}],howTo:[{text:`Per model: in the service, open the semantic model’s Settings, expand Large semantic model storage format, turn it On, and select Apply. Then refresh to load history.`,sources:[Z]},{text:`Per workspace default: in workspace settings on a Premium/Fabric capacity, set Default storage format to Large semantic model storage format. PowerShell (Set-PowerBIDataset -TargetStorageMode PremiumFiles) also works.`,sources:[Z]}]}],examples:[],traps:[{text:`Large format raises the limit in the service only. Publishing from Power BI Desktop is still capped at 10 GB, and models grow beyond that through refresh in the service.`,sources:[Z]},{text:`Semantic models in Pro workspaces don’t support XMLA write operations.`,sources:[Z]},{text:`Large format is about the in-memory model size limit. Direct Lake models are governed instead by capacity guardrails such as max model size on disk and max memory per SKU.`,sources:[Z,H]}],dontConfuse:[],renamed:[],preview:[],upcoming:[],glossary:[{term:`Large semantic model storage format`,definition:`A semantic model setting that allows a model to grow beyond the default 1 GB limit up to the capacity limit, and improves XMLA write performance.`,sources:[Z]},{term:`On-demand load`,definition:`For large-format models, loading only the needed data pages into memory when queried, instead of the whole model.`,sources:[Z]}],needsVerification:[]},{machineId:`double-loom`,overview:[{text:`A composite model mixes storage modes or sources in one model, for example DirectQuery facts with Import or Dual dimensions, or a local model that extends a published semantic model with new tables and measures. It combines in-memory speed with real-time or federated data.`,sources:[V,W]}],bullets:[{bulletId:`S1.7`,tools:[`semantic-model`,`power-bi-desktop`],concepts:[{text:`A source group is the set of tables from one DirectQuery source, or all Import sources together. Direct Lake and Import tables count as the same source group. Learn says a composite model is made of one or more source groups.`,sources:[W]},{text:`Relationships that cross source groups are always limited relationships.`,sources:[W,q]},{text:`Typical design: dimensions in Import or Dual, facts in DirectQuery. Dual lets the engine generate a single efficient native query joining the fact to its filtered dimension.`,sources:[V]},{text:`Hybrid tables: one table with Import partitions plus one DirectQuery partition for the latest data. They are created by an incremental refresh policy with real-time DirectQuery.`,sources:[V,Q]}],howTo:[{text:`Extend a published model: in Power BI Desktop connect live to the semantic model, then choose Make changes to this model. This converts the live connection to DirectQuery and creates a local model where you can add Import or DirectQuery tables.`,sources:[W]},{text:`Direct Lake: Direct Lake on OneLake tables can be combined with Import tables (in web modeling) and DirectQuery tables (with XMLA tools). Direct Lake on SQL can’t be mixed with other modes in the same model, but you can build a composite model on top of it in Desktop.`,sources:[H]}]}],examples:[],traps:[{text:`Security: in a composite model, values from one source can be sent inside queries to another source (for example names from a spreadsheet inside SQL sent to a database). Power BI warns you when you create one.`,sources:[W]},{text:`A report built on composite model C, which includes a table from model A, can query any table in model A that isn’t protected by RLS.`,sources:[W]},{text:`Chaining: models built on other models form a chain, and the maximum length of a chain is three models.`,sources:[W]},{text:`Calculated tables in a composite model use Import storage even when they reference DirectQuery tables.`,sources:[H]}],dontConfuse:[{pairId:`dual-vs-hybrid`,a:`Dual table`,b:`Hybrid table`,difference:[{text:`A Dual table is one table that can be served from cache or by DirectQuery, chosen per query (usually a dimension). A hybrid table is a partitioned table, usually a fact, with Import partitions for history and one DirectQuery partition for the newest data.`,sources:[V,jt]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Composite model`,definition:`A semantic model made of one or more source groups, for example one that combines tables with different storage modes or adds to a model it connects to.`,sources:[H,W]},{term:`Source group`,definition:`The tables and relationships from one DirectQuery source, or all Import (and Direct Lake) sources, in a model.`,sources:[W]},{term:`Hybrid table`,definition:`A table with Import partitions plus a DirectQuery partition for real-time data, usually created by incremental refresh.`,sources:[V]},{term:`Chaining`,definition:`Building semantic models on top of other semantic models, which creates a dependency chain.`,sources:[W]}],needsVerification:[]},{machineId:`speed-governor`,pl300Adds:[{text:`PL-300 covered Performance Analyzer, DAX query view, and removing unneeded rows and columns. DP-600 adds Fabric-scale concerns: diagnosing Direct Lake fallback to DirectQuery (Performance Analyzer shows a Direct query duration; SQL Server Profiler shows DirectQuery events), Delta table health, and DAX patterns that use the storage engine efficiently.`,sources:[Mt,H,Jt]}],overview:[{text:`Slow reports usually come from too much data in visuals, too many visuals, inefficient DAX, or (in Fabric) queries that fall back from Direct Lake. Measure first with Performance Analyzer, then fix the model, the DAX, or the report design.`,sources:[Gt,Kt,Mt]}],bullets:[{bulletId:`S2.1`,tools:[`power-bi-desktop`,`semantic-model`],concepts:[{text:`Performance Analyzer splits each visual’s load time into DAX query, Direct query (time for the source to answer), Visual display, and Other (preparing queries, waiting on other visuals). You can copy each visual’s DAX query into DAX query view.`,sources:[Gt]},{text:`Report design: apply the most restrictive filters (for example Top N on large tables), limit the number of visuals per page (use drillthrough and tooltips), and test custom visuals for performance.`,sources:[Kt]},{text:`Model size (Import): remove unnecessary columns and rows, group and summarize, optimize column data types, disable auto date/time, and disable load for helper Power Query queries.`,sources:[qt]}],howTo:[{text:`In Desktop: View > Performance analyzer > Start recording > Refresh visuals, then expand each visual to see the breakdown. For Direct Lake, a Direct query line means that visual’s query fell back.`,sources:[Gt,Mt]}]},{bulletId:`S2.2`,tools:[`semantic-model`,`power-bi-desktop`],concepts:[{text:`Pass CALCULATE filters as Boolean expressions (optionally wrapped in KEEPFILTERS) instead of FILTER over a whole table. In-memory column stores are optimized to filter columns.`,sources:[Jt]},{text:`Use DIVIDE instead of testing the denominator with IF. It handles zero or blank denominators and is better optimized.`,sources:[Yt]},{text:`Use COUNTROWS instead of COUNT on a column to count table rows. It is more efficient.`,sources:[Xt]},{text:`Store repeated sub-expressions in variables so they’re evaluated once.`,sources:[Ft]}],howTo:[{text:`Copy a slow visual’s query from Performance Analyzer into DAX query view, rewrite the measure as a DEFINE MEASURE, compare timings, then update the model.`,sources:[Gt,Qt]}]}],examples:[{title:`Replace a table filter with a Boolean filter`,language:`dax`,illustrative:!0,steps:[{code:`Red Sales (slow) =
CALCULATE([Sales], FILTER('Product', 'Product'[Color] = "Red"))`,explain:`FILTER iterates every Product row to build a table filter, and it replaces existing filters on Product.`},{code:`Red Sales =
CALCULATE([Sales], KEEPFILTERS('Product'[Color] = "Red"))`,explain:`A Boolean filter on one column is optimized by the column store. KEEPFILTERS keeps any existing Color filter instead of overwriting it.`}],sources:[Jt]},{title:`Safe division and row counting`,language:`dax`,illustrative:!0,steps:[{code:`Profit Margin = DIVIDE([Profit], [Sales])`,explain:`Returns BLANK when Sales is zero or blank, with no IF needed, and it is faster than testing the denominator yourself.`},{code:`Sales Orders = COUNTROWS(Sales)`,explain:`Counts table rows directly, which is more efficient than COUNT over a column.`}],sources:[Yt,Xt]}],traps:[{text:`Boolean filter arguments can’t reference columns from multiple tables or reference a measure. Use FILTER only when you need those.`,sources:[Jt]},{text:`An unfiltered table visual over a huge model loads every row. Learn suggests a Top N filter on the visual.`,sources:[Kt]},{text:`In SQL Server Profiler, DirectQuery Begin/End events suggest Direct Lake fallback, but EngineEdition and OLS check queries always use DirectQuery and don’t mean fallback.`,sources:[Mt]}],dontConfuse:[{pairId:`perf-categories`,a:`DAX query time`,b:`Visual display time`,difference:[{text:`DAX query is time spent by the semantic model producing results, which you fix with model or DAX changes. Visual display is time spent drawing the visual, which you fix with report design (fewer points, simpler visuals).`,sources:[Gt]}]}],renamed:[],preview:[{feature:`Performance Analyzer: Evaluated parameters`,note:`A duration category for evaluating field parameters in a visual, labelled preview on Learn.`,sources:[Gt]}],upcoming:[],glossary:[{term:`Performance Analyzer`,definition:`A Power BI Desktop pane that records how long each visual takes to load, broken into DAX query, Direct query, Visual display, and Other.`,sources:[Gt]},{term:`KEEPFILTERS`,definition:`A DAX modifier that makes a CALCULATE filter intersect existing filters on the same column instead of replacing them.`,sources:[Jt]},{term:`Auto date/time`,definition:`A Power BI Desktop option that creates hidden date tables for date columns. Learn recommends disabling it to reduce model size.`,sources:[qt]}],needsVerification:[]},{machineId:`direct-lake-shuttle`,overview:[{text:`Direct Lake lets a semantic model query huge Delta tables at Import-like speed without copying them. To configure it you need to understand framing (what "refresh" means), automatic updates, guardrails, and DirectQuery fallback, and choose between its two flavors.`,sources:[H,U]}],bullets:[{bulletId:`S2.3`,tools:[`semantic-model`,`lakehouse`,`warehouse`,`sql-analytics-endpoint`],concepts:[{text:`Transcoding: columns load from OneLake only when a query first needs them, then stay resident in memory.`,sources:[U]},{text:`Framing is the Direct Lake refresh. It reads the latest Delta log, points the model at the current Parquet files, and fixes the point in time that queries see. Data written after the last framing isn’t visible until the next one.`,sources:[U]},{text:`Automatic updates ("Keep your Direct Lake data up to date") is on by default and reframes whenever the Delta tables change. Turn it off to hide half-finished ETL from users, then refresh manually, on a schedule, or through the REST API or TOM after the load.`,sources:[U]},{text:`Fallback (Direct Lake on SQL only): a query switches to DirectQuery through the SQL analytics endpoint when it uses tables with SQL RLS, unmaterialized SQL views, or a table over a guardrail, or when the model wasn’t reframed after the tables changed. How Direct Lake works also lists dynamic data masking (DDM) defined at the SQL analytics endpoint as a cause. SQL OLS or CLS also keep a query out of Direct Lake, but Learn pages differ on the result (see “Learn pages disagree”).`,sources:[U,Nt]},{text:`Default fallback behavior: the DirectLakeBehavior property defaults to Automatic, which falls back silently. DirectLakeOnly makes such queries fail; DirectQueryOnly forces DirectQuery, for testing.`,sources:[U]}],howTo:[{text:`Set Direct Lake behavior in Model view > model Properties (or with TOM/TMSL). Learn suggests Automatic in production, DirectLakeOnly in development to surface problems, and DirectQueryOnly to measure fallback cost.`,sources:[U]},{text:`Avoid fallback: keep Delta tables within the SKU guardrails (Parquet files, row groups, rows), avoid SQL views and SQL-level security on tables the model uses, and refresh after schema changes.`,sources:[U,H]},{text:`Detect fallback with Performance Analyzer (a Direct query line appears) or SQL Server Profiler (DirectQuery_Begin/End events).`,sources:[Mt]}]},{bulletId:`S2.4`,tools:[`semantic-model`,`onelake`,`sql-analytics-endpoint`],concepts:[{text:`Direct Lake on OneLake can use Delta tables from one or more Fabric items, never falls back to DirectQuery (it runs DirectLakeOnly), can be combined with Import tables, and is Learn’s recommended option for new models.`,sources:[H,U]},{text:`Direct Lake on SQL analytics endpoints uses a single Fabric source, discovers tables and views and checks permissions through the SQL analytics endpoint, can read SQL views (by falling back), and falls back when it can’t read Delta directly.`,sources:[H]},{text:`Sources: both support lakehouses, warehouses, SQL databases, and mirrored databases. Only on OneLake supports KQL databases (with OneLake availability on) and Cosmos DB. Only on SQL supports Snowflake databases.`,sources:[H]}],howTo:[{text:`Choose on OneLake when you need multiple sources, Import tables in the same model, or KQL data, and don’t need SQL views. Choose on SQL when you must use SQL views or the SQL endpoint’s security, and you accept DirectQuery fallback.`,sources:[H]},{text:`On OneLake, permissions aren’t checked through the SQL analytics endpoint: users need access to the OneLake files (or OneLake security roles). Learn pages differ on what a query against a table with SQL endpoint RLS then returns: the overview says it succeeds without the SQL RLS, while Integrate Direct Lake security says it returns an error. Either way, enforce row filters with semantic model RLS or OneLake security.`,sources:[H,Nt]}]}],examples:[],traps:[{text:`Over a guardrail, Direct Lake on OneLake behaves like Import: refresh fails and the model can’t be queried until the tables are optimized. Direct Lake on SQL falls back to DirectQuery (if enabled), and the refresh succeeds with a warning.`,sources:[H]},{text:`You can’t build a Direct Lake on OneLake table on a non-materialized SQL view. Use a lakehouse materialized view, or Import.`,sources:[H]},{text:`The semantic model and its Direct Lake source must be in the same region. The workaround is a shortcut from a lakehouse in the model’s region.`,sources:[H]},{text:`Direct Lake tables don’t support complex Delta column types, binary or GUID types, or NaN values, and string values are capped at 32,764 characters.`,sources:[H]},{text:`Power BI suspends automatic updates after a non-recoverable refresh error. They resume after a successful on-demand refresh.`,sources:[U]}],dontConfuse:[{pairId:`dl-onelake-vs-sql`,a:`Direct Lake on OneLake`,b:`Direct Lake on SQL analytics endpoint`,difference:[{text:`Sources: OneLake = one or more Fabric items with Delta tables; SQL = a single item with a SQL analytics endpoint.`,sources:[H]},{text:`Fallback: OneLake never falls back (DirectLakeOnly). SQL falls back to DirectQuery under the DirectLakeBehavior setting.`,sources:[U,H]},{text:`SQL views and SQL security: OneLake can’t use non-materialized views and doesn’t check SQL endpoint security (Learn pages differ on whether such queries succeed or error). SQL can read views and respects SQL RLS by falling back.`,sources:[H,Nt]},{text:`Mixing modes: OneLake can mix with Import (and DirectQuery via XMLA tools); SQL can’t mix storage modes in the same model.`,sources:[H]}]},{pairId:`dl-fallback`,a:`Direct Lake query (no fallback)`,b:`DirectQuery fallback`,difference:[{text:`Without fallback, VertiPaq answers from columns paged in from OneLake as of the last framing. With fallback, the query goes to the SQL analytics endpoint in DirectQuery: always the latest data but usually slower. Only Direct Lake on SQL can fall back. DirectLakeBehavior = Automatic (default, silent fallback), DirectLakeOnly (error instead), or DirectQueryOnly (always fall back).`,sources:[U,H]}]},{pairId:`framing-vs-import-refresh`,a:`Direct Lake refresh (framing)`,b:`Import refresh`,difference:[{text:`Framing copies only metadata: it re-points the model to the newest Delta files in seconds. An Import refresh copies the data itself and can take a long time and a lot of capacity memory and CPU.`,sources:[H,U]}]}],renamed:[],preview:[{feature:`Calculated tables in Direct Lake on OneLake`,note:`Supported in preview, with limitations.`,sources:[H]},{feature:`Calculated columns in Direct Lake on OneLake`,note:`"User Context only" calculated columns are in preview.`,sources:[H]}],upcoming:[],glossary:[{term:`Direct Lake on OneLake`,definition:`The Direct Lake option that reads Delta tables from one or more Fabric items directly in OneLake and never falls back to DirectQuery.`,sources:[H]},{term:`Direct Lake on SQL analytics endpoint`,definition:`The Direct Lake option that uses one item’s SQL analytics endpoint for discovery and permission checks and can fall back to DirectQuery.`,sources:[H]},{term:`Framing`,definition:`The Direct Lake refresh operation that updates the model to reference the latest Delta table version, setting the point in time queries see.`,sources:[U]},{term:`Transcoding`,definition:`Direct Lake’s on-demand loading of a column from OneLake into memory the first time a query needs it.`,sources:[U]},{term:`DirectQuery fallback`,definition:`When a Direct Lake on SQL query can’t be served from Delta and runs as DirectQuery against the SQL analytics endpoint instead.`,sources:[U]},{term:`DirectLakeBehavior`,definition:`A model property (Automatic, DirectLakeOnly, DirectQueryOnly) that controls fallback for Direct Lake on SQL models.`,sources:[U]},{term:`Guardrails (Direct Lake)`,definition:`Per-SKU limits on Parquet files, row groups, and rows per table, and on model size, that determine whether a Direct Lake table can be served.`,sources:[H]}],contested:[{topic:`Direct Lake on SQL: a query that touches a table or column restricted by SQL analytics endpoint OLS or CLS`,readings:[{text:`How Direct Lake works lists "OLS defined at SQL analytics endpoint" as a fallback cause, with the fix "Move object-level security to the semantic model, or accept DirectQuery fallback."`,sources:[U]},{text:`Integrate Direct Lake security says that if a query touches a table or column restricted by SQL analytics endpoint OLS or CLS, "the query returns an error".`,sources:[Nt]}],guidance:`Either way the query isn’t answered in Direct Lake mode; How Direct Lake works suggests moving object-level security to the semantic model. No question or puzzle depends on fallback vs error here.`},{topic:`Direct Lake on OneLake when the SQL analytics endpoint enforces RLS on the table`,readings:[{text:`The Direct Lake overview says that with Direct Lake on OneLake "queries will succeed, and SQL based RLS is not applied", because Direct Lake on OneLake reads the files in OneLake.`,sources:[H]},{text:`Integrate Direct Lake security says Direct Lake on OneLake doesn’t fall back to DirectQuery, and if any table in the SQL analytics endpoint enforces RLS, "an error result is returned".`,sources:[Nt]}],guidance:`Under neither reading does Direct Lake on OneLake apply the SQL endpoint’s RLS to the rows it returns. Integrate Direct Lake security recommends enforcing data-access rules in OneLake security. No question or puzzle depends on success vs error here.`}],needsVerification:[]},{machineId:`batch-winder`,pl300Adds:[{text:`Incremental refresh isn’t in the current PL-300 outline; the closest PL-300 skill is scheduled refresh. For DP-600, learn the RangeStart/RangeEnd filter, the policy settings (archive vs refresh period, detect data changes, complete days only), query folding, and real-time hybrid partitions.`,sources:[Q,$]}],overview:[{text:`Incremental refresh splits a large Import table into date-based partitions, so each refresh reloads only recent data while history stays untouched. Refreshes get faster, cheaper, and more reliable. Optionally a real-time DirectQuery partition adds the latest rows.`,sources:[Q]}],bullets:[{bulletId:`S2.5`,tools:[`semantic-model`,`power-bi-desktop`],concepts:[{text:`Two Power Query parameters with the reserved, case-sensitive names RangeStart and RangeEnd (Date/Time type) filter the table on a date column. In the service they are overridden automatically for each partition.`,sources:[Q,$]},{text:`Policy settings: Archive data starting before refresh date (how much history to keep, stored in year/quarter/month partitions), Incrementally refresh data starting before refresh date (the window reloaded each time), plus optional Detect data changes, Only refresh complete days, and Get the latest data in real time with DirectQuery.`,sources:[$]},{text:`Query folding matters: the RangeStart/RangeEnd filter should fold to the source. Otherwise an Import-only policy may pull all rows and filter locally, and a real-time policy can’t use non-folding steps at all.`,sources:[Q]},{text:`Supported for Premium, PPU, Pro, and Embedded models. The real-time DirectQuery option needs Premium, PPU, or Embedded.`,sources:[Q]}],howTo:[{text:`In Power BI Desktop: create RangeStart and RangeEnd parameters, filter the date column with >= RangeStart and < RangeEnd, then in Table view right-click the table in the Data pane > Incremental refresh and define the policy. Publish, then run the first refresh in the service to build the partitions.`,sources:[$]},{text:`For integer date keys (yyyymmdd), convert RangeStart and RangeEnd to the same integer format inside the filter.`,sources:[Q]}]}],examples:[{title:`The RangeStart/RangeEnd filter step (Power Query M)`,language:`m`,illustrative:!0,steps:[{code:`#"Filtered Rows" = Table.SelectRows(#"Changed Type",
    each [OrderDate] >= RangeStart and [OrderDate] < RangeEnd)`,explain:`Keep rows from RangeStart (inclusive) up to RangeEnd (exclusive). Having "=" on only one side means no row lands in two partitions.`},{code:`#"Filtered Rows" = Table.SelectRows(Data,
    each [OrderDateKey] >= Int32.From(DateTime.ToText(RangeStart, [Format="yyyyMMdd"]))
     and [OrderDateKey] <  Int32.From(DateTime.ToText(RangeEnd,   [Format="yyyyMMdd"])))`,explain:`Variant for an integer yyyymmdd key: convert the Date/Time parameters to the same integer form before comparing.`}],sources:[$,Q]}],traps:[{text:`Using ">=" and "<=" on both parameters can put a boundary row in two partitions and duplicate data.`,sources:[$]},{text:`After publishing a model with incremental refresh, you can’t download it back to Power BI Desktop as a .pbix.`,sources:[Q]},{text:`The Detect data changes column must be different from the column used for RangeStart/RangeEnd partitioning.`,sources:[$]},{text:`If several tables have policies, they must all use the same RangeStart and RangeEnd parameters, even with different periods.`,sources:[Q]},{text:`Direct Lake tables don’t use incremental refresh partitions. Partition the Delta tables instead.`,sources:[H]}],dontConfuse:[{pairId:`archive-vs-refresh-period`,a:`Archive (store) period`,b:`Incremental refresh period`,difference:[{text:`The archive period is how much history the table keeps (for example 5 years); those partitions aren’t reloaded. The refresh period is the recent window reloaded on every refresh (for example 3 days).`,sources:[$]}]}],renamed:[],preview:[],upcoming:[],glossary:[{term:`Incremental refresh`,definition:`A refresh policy that partitions a table by date so only recent partitions reload on each refresh.`,sources:[Q]},{term:`RangeStart / RangeEnd`,definition:`Reserved, case-sensitive Date/Time Power Query parameters used to filter a table for incremental refresh. The service overrides them per partition.`,sources:[Q,$]},{term:`Query folding`,definition:`Power Query pushing transformation steps (like the RangeStart/RangeEnd filter) down to the source as a native query.`,sources:[Q]},{term:`Detect data changes`,definition:`An incremental refresh option that only refreshes periods whose audit date/time column shows a change.`,sources:[$]}],needsVerification:[]}],rn=ee({allNotes:()=>an,notesByMachine:()=>on}),an=[...Re,...At,...nn,...Te],on=new Map(an.map(ee=>[ee.machineId,ee]));export{on as n,rn as r,an as t};